/****************************************************************************
 * Contest 2026 team 008 - charging station demo
 *
 * A desktop charging station application for openvela.
 * Displays charging status and battery level on the screen.
 ****************************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>

#include <nuttx/config.h>
#include <nuttx/input/touchscreen.h>

#ifdef CONFIG_GRAPHICS_LVGL
#  include <lvgl/lvgl.h>
#endif

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#ifndef CONFIG_EXAMPLES_CHARGING_STATION_DEVPATH
#  define CONFIG_EXAMPLES_CHARGING_STATION_DEVPATH "/dev/input0"
#endif

#define CHARGING_STATION_POLL_MSEC 1000

/****************************************************************************
 * Private Data
 ****************************************************************************/

static int g_charging_station_fd = -1;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: charging_station_open_touch
 *
 * Open the touchscreen device for reading touch events.
 ****************************************************************************/

static int charging_station_open_touch(void)
{
  int fd = open(CONFIG_EXAMPLES_CHARGING_STATION_DEVPATH, O_RDONLY);
  if (fd < 0)
    {
      fprintf(stderr, "charging_station: failed to open %s: %d\n",
              CONFIG_EXAMPLES_CHARGING_STATION_DEVPATH, errno);
    }

  return fd;
}

/****************************************************************************
 * Name: charging_station_read_touch
 *
 * Read one touch sample from the touchscreen device.
 ****************************************************************************/

static void charging_station_read_touch(int fd, struct touch_sample_s *sample)
{
  ssize_t nbytes = read(fd, sample, sizeof(struct touch_sample_s));
  if (nbytes == (ssize_t)sizeof(struct touch_sample_s))
    {
      printf("Touch: x=%d y=%d flags=0x%02x\n",
             sample->point[0].x,
             sample->point[0].y,
             sample->point[0].flags);
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: charging_station_main
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  struct touch_sample_s sample;

  printf("=== Charging Station Demo ===\n");
  printf("Team: contest2026_008\n");
  printf("Board: STM32H750B-DK\n");

  /* Open the touchscreen device */
  g_charging_station_fd = charging_station_open_touch();
  if (g_charging_station_fd < 0)
    {
      printf("Touchscreen not available, continuing without it.\n");
    }

  /* Main loop: poll touch input and display status */
  while (1)
    {
      if (g_charging_station_fd >= 0)
        {
          charging_station_read_touch(g_charging_station_fd, &sample);
        }

      /* TODO: add battery level monitoring and charging control */
      usleep(CHARGING_STATION_POLL_MSEC * 1000);
    }

  if (g_charging_station_fd >= 0)
    {
      close(g_charging_station_fd);
    }

  return 0;
}

