/****************************************************************************
 * Contest 2026 team 008 - charging station UI
 *
 * LVGL UI for the desktop charging station.
 * Shows battery level, charging status and slot control on the screen.
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>

#include <lvgl/lvgl.h>

#include "charging_station_ui.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define CS_SLOT_COUNT       4
#define CS_SLOT_GAP         10
#define CS_SLOT_MARGIN      20

/* Colors */
#define CS_COLOR_BG         lv_color_hex(0x1E1E2E)
#define CS_COLOR_CARD       lv_color_hex(0x2E2E3E)
#define CS_COLOR_CHARGING   lv_color_hex(0x00C853)
#define CS_COLOR_FULL       lv_color_hex(0x00B0FF)
#define CS_COLOR_IDLE       lv_color_hex(0x8E8E9E)
#define CS_COLOR_TEXT       lv_color_hex(0xEEEEEE)
#define CS_COLOR_ACCENT     lv_color_hex(0xFFA000)

/****************************************************************************
 * Private Types
 ****************************************************************************/

typedef struct
{
  lv_obj_t *card;            /* Card background */
  lv_obj_t *label_slot;      /* "Slot 1" label */
  lv_obj_t *bar;             /* Battery bar */
  lv_obj_t *label_pct;       /* "68%" label */
  lv_obj_t *label_status;    /* "Charging" / "Full" / "Idle" */
  int       battery_pct;     /* Simulated battery level */
  bool      charging;        /* Charging state */
} cs_slot_t;

/****************************************************************************
 * Private Data
 ****************************************************************************/

static cs_slot_t g_slots[CS_SLOT_COUNT];

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: cs_slot_update
 *
 * Refresh a slot's bar and labels from its state.
 ****************************************************************************/

static void cs_slot_update(cs_slot_t *slot)
{
  const char *status_str;
  lv_color_t  status_color;

  /* Update battery bar */
  lv_bar_set_value(slot->bar, slot->battery_pct, LV_ANIM_ON);

  /* Update percentage label */
  lv_label_set_text_fmt(slot->label_pct, "%d%%", slot->battery_pct);

  /* Update status text and color */
  if (slot->charging)
    {
      status_str  = "Charging";
      status_color = CS_COLOR_CHARGING;
    }
  else if (slot->battery_pct >= 100)
    {
      status_str  = "Full";
      status_color = CS_COLOR_FULL;
    }
  else
    {
      status_str  = "Idle";
      status_color = CS_COLOR_IDLE;
    }

  lv_label_set_text(slot->label_status, status_str);
  lv_obj_set_style_text_color(slot->label_status, status_color, 0);

  /* Card border color shows charging state */
  lv_obj_set_style_border_color(slot->card, status_color, 0);
}

/****************************************************************************
 * Name: cs_slot_create
 *
 * Create one charging slot card at the given position.
 ****************************************************************************/

static void cs_slot_create(cs_slot_t *slot, lv_obj_t *parent,
                           int index, lv_coord_t x, lv_coord_t y,
                           lv_coord_t w, lv_coord_t h)
{
  /* Card container */
  slot->card = lv_obj_create(parent);
  lv_obj_set_pos(slot->card, x, y);
  lv_obj_set_size(slot->card, w, h);
  lv_obj_set_style_bg_color(slot->card, CS_COLOR_CARD, 0);
  lv_obj_set_style_border_width(slot->card, 3, 0);
  lv_obj_set_style_border_color(slot->card, CS_COLOR_IDLE, 0);
  lv_obj_set_style_radius(slot->card, 12, 0);
  lv_obj_set_style_pad_all(slot->card, 10, 0);

  /* Slot title */
  slot->label_slot = lv_label_create(slot->card);
  lv_label_set_text_fmt(slot->label_slot, "Slot %d", index + 1);
  lv_obj_set_style_text_color(slot->label_slot, CS_COLOR_TEXT, 0);
  lv_obj_set_style_text_font(slot->label_slot, &lv_font_montserrat_16, 0);

  /* Battery level bar */
  slot->bar = lv_bar_create(slot->card);
  lv_obj_set_size(slot->bar, w - 40, 20);
  lv_obj_align(slot->bar, LV_ALIGN_TOP_MID, 0, 30);
  lv_obj_set_style_bg_color(slot->bar, lv_color_hex(0x44445A), 0);
  lv_obj_set_style_bg_color(slot->bar, CS_COLOR_ACCENT, LV_PART_INDICATOR);
  lv_bar_set_range(slot->bar, 0, 100);

  /* Percentage label */
  slot->label_pct = lv_label_create(slot->card);
  lv_label_set_text_fmt(slot->label_pct, "0%%");
  lv_obj_align(slot->label_pct, LV_ALIGN_TOP_MID, 0, 55);
  lv_obj_set_style_text_color(slot->label_pct, CS_COLOR_TEXT, 0);
  lv_obj_set_style_text_font(slot->label_pct, &lv_font_montserrat_20, 0);

  /* Status label */
  slot->label_status = lv_label_create(slot->card);
  lv_label_set_text(slot->label_status, "Idle");
  lv_obj_align(slot->label_status, LV_ALIGN_BOTTOM_MID, 0, -10);
  lv_obj_set_style_text_color(slot->label_status, CS_COLOR_IDLE, 0);
  lv_obj_set_style_text_font(slot->label_status, &lv_font_montserrat_14, 0);

  /* Initial state */
  slot->battery_pct = 0;
  slot->charging    = false;
}

/****************************************************************************
 * Name: cs_timer_cb
 *
 * Periodic timer that simulates charging progress.
 * In a real product this would read ADC / battery gauge over I2C.
 ****************************************************************************/

static void cs_timer_cb(lv_timer_t *timer)
{
  int i;

  for (i = 0; i < CS_SLOT_COUNT; i++)
    {
      cs_slot_t *slot = &g_slots[i];

      if (slot->charging)
        {
          /* Charge 1% every second until full */
          if (slot->battery_pct < 100)
            {
              slot->battery_pct++;
            }
          else
            {
              slot->charging = false;  /* Auto stop at 100% */
            }
        }

      cs_slot_update(slot);
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: cs_ui_init
 *
 * Build the full charging station UI.
 ****************************************************************************/

int cs_ui_init(lv_obj_t *scr)
{
  lv_coord_t scr_w = lv_display_get_horizontal_resolution(lv_screen_active());
  lv_coord_t scr_h = lv_display_get_vertical_resolution(lv_screen_active());
  lv_coord_t slot_w;
  lv_coord_t slot_h;
  lv_coord_t card_h;
  int i;

  /* Background */
  lv_obj_set_style_bg_color(scr, CS_COLOR_BG, 0);

  /* Title */
  lv_obj_t *title = lv_label_create(scr);
  lv_label_set_text(title, "Charging Station");
  lv_obj_align(title, LV_ALIGN_TOP_MID, 0, 15);
  lv_obj_set_style_text_color(title, CS_COLOR_TEXT, 0);
  lv_obj_set_style_text_font(title, &lv_font_montserrat_24, 0);

  /* Slot grid: 2 columns x 2 rows */
  slot_w = (scr_w - CS_SLOT_MARGIN * 2 - CS_SLOT_GAP) / 2;
  card_h = (scr_h - 70 - CS_SLOT_GAP) / 2;
  slot_h = card_h;

  for (i = 0; i < CS_SLOT_COUNT; i++)
    {
      lv_coord_t x = CS_SLOT_MARGIN +
                     (i % 2) * (slot_w + CS_SLOT_GAP);
      lv_coord_t y = 70 + (i / 2) * (card_h + CS_SLOT_GAP);

      cs_slot_create(&g_slots[i], scr, i, x, y, slot_w, slot_h);
    }

  /* Demo initial state: slot 0 charging at 68% */
  g_slots[0].battery_pct = 68;
  g_slots[0].charging    = true;
  /* Slot 1 idle at 35% */
  g_slots[1].battery_pct = 35;
  /* Slot 2 full */
  g_slots[2].battery_pct = 100;
  /* Slot 3 empty, idle */

  for (i = 0; i < CS_SLOT_COUNT; i++)
    {
      cs_slot_update(&g_slots[i]);
    }

  /* Refresh every 1 second */
  lv_timer_create(cs_timer_cb, 1000, NULL);

  return 0;
}

/****************************************************************************
 * Contest 2026 team 008 - charging station main
 *
 * Entry point: initializes LVGL, display and touchscreen, then
 * enters the LVGL event loop.
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>

#include <lvgl/lvgl.h>

#include "charging_station_ui.h"

/****************************************************************************
 * Private Functions
 ****************************************************************************/

#ifdef CONFIG_LV_USE_NUTTX_LIBUV
/* libuv event loop variant (used when CONFIG_LV_USE_NUTTX_LIBUV=y) */
#include <uv.h>

static void lv_nuttx_uv_loop(uv_loop_t *loop, lv_nuttx_result_t *result)
{
  lv_nuttx_uv_t uv_info;
  void *data;

  uv_loop_init(loop);

  lv_memset(&uv_info, 0, sizeof(uv_info));
  uv_info.loop = loop;
  uv_info.disp = result->disp;
  uv_info.indev = result->indev;
#ifdef CONFIG_UINPUT_TOUCH
  uv_info.uindev = result->utouch_indev;
#endif

  data = lv_nuttx_uv_init(&uv_info);
  uv_run(loop, UV_RUN_DEFAULT);
  lv_nuttx_uv_deinit(&data);
}
#else
static void lv_nuttx_loop(void)
{
  while (1)
    {
      uint32_t idle;

      idle = lv_timer_handler();
      idle = idle ? idle : 1;
      usleep(idle * 1000);
    }
}
#endif

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  lv_nuttx_dsc_t info;
  lv_nuttx_result_t result;
#ifdef CONFIG_LV_USE_NUTTX_LIBUV
  uv_loop_t ui_loop;
#endif
  int ret;

  syslog(LOG_INFO, "Charging Station starting\n");

  if (lv_is_initialized())
    {
      syslog(LOG_ERR, "Charging Station: LVGL already initialized\n");
      return -1;
    }

  lv_init();

  lv_nuttx_dsc_init(&info);

  /* Use framebuffer display */
#ifdef CONFIG_LV_USE_NUTTX_LCD
  info.fb_path = "/dev/lcd0";
#endif

  lv_nuttx_init(&info, &result);

  if (result.disp == NULL)
    {
      syslog(LOG_ERR, "Charging Station: display init failed\n");
      lv_deinit();
      return -1;
    }

  /* Build the charging station UI */
  ret = cs_ui_init(result.disp);
  if (ret < 0)
    {
      syslog(LOG_ERR, "Charging Station: UI init failed: %d\n", ret);
      lv_nuttx_deinit(&result);
      lv_deinit();
      return ret;
    }

  syslog(LOG_INFO, "Charging Station: display res=%ldx%ld\n",
         (long)lv_display_get_horizontal_resolution(result.disp),
         (long)lv_display_get_vertical_resolution(result.disp));

  /* Ensure touchscreen indev is in timer (poll) mode */
  if (result.indev)
    {
      lv_indev_set_mode(result.indev, LV_INDEV_MODE_TIMER);
      lv_timer_t *t = lv_indev_get_read_timer(result.indev);
      if (t)
        {
          lv_timer_set_period(t, 30);
          syslog(LOG_INFO, "Charging Station: indev timer set to 30ms\n");
        }
      else
        {
          syslog(LOG_ERR, "Charging Station: indev has no timer!\n");
        }
    }
  else
    {
      syslog(LOG_ERR, "Charging Station: indev is NULL!\n");
    }

#ifdef CONFIG_LV_USE_NUTTX_LIBUV
  syslog(LOG_INFO, "Charging Station: entering libuv event loop\n");
  lv_nuttx_uv_loop(&ui_loop, &result);
#else
  syslog(LOG_INFO, "Charging Station: entering poll loop\n");
  lv_nuttx_loop();
#endif

  lv_nuttx_deinit(&result);
  lv_deinit();

  syslog(LOG_INFO, "Charging Station exiting\n");
  return 0;
}

