          syslog(LOG_INFO, "Charging Station: indev timer set to 30ms\n");
        }
      else
        {
          syslog(LOG_ERR, "Charging Station: indev has no timer!\n");
        }
    }
  else
    {
      syslog(LOG_ERR, "Charging Station: indev is NULL!\n");
    }

#ifdef CONFIG_LV_USE_NUTTX_LIBUV
  syslog(LOG_INFO, "Charging Station: entering libuv event loop\n");
  lv_nuttx_uv_loop(&ui_loop, &result);
#else
  syslog(LOG_INFO, "Charging Station: entering poll loop\n");
  lv_nuttx_loop();
#endif

  lv_nuttx_deinit(&result);
  lv_deinit();

  syslog(LOG_INFO, "Charging Station exiting\n");
  return 0;
}

/****************************************************************************
 * Contest 2026 team 008 - charging station main
 *
 * Simple LVGL touch test: one button + coordinate display.
 * Touch the screen and see if the button reacts.
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>

#include <lvgl/lvgl.h>

/****************************************************************************
 * Private Data
 ****************************************************************************/

static lv_obj_t *g_btn;
static lv_obj_t *g_label_coord;
static int g_touch_count = 0;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: btn_cb
 *
 * Button event callback - runs when the button is pressed/released.
 ****************************************************************************/

static void btn_cb(lv_event_t *e)
{
  lv_event_code_t code = lv_event_get_code(e);

  if (code == LV_EVENT_PRESSED)
    {
      lv_obj_set_style_bg_color(g_btn, lv_color_hex(0x00C853), 0);
      lv_label_set_text_fmt(lv_obj_get_child(g_btn, 0),
                            "PRESSED! %d", ++g_touch_count);
    }
  else if (code == LV_EVENT_RELEASED)
    {
      lv_obj_set_style_bg_color(g_btn, lv_color_hex(0x00B0FF), 0);
      lv_label_set_text_fmt(lv_obj_get_child(g_btn, 0),
                            "Touch %d", g_touch_count);
    }
}

/****************************************************************************
 * Name: lv_nuttx_loop
 *
 * Standard LVGL poll loop.
 ****************************************************************************/

static void lv_nuttx_loop(void)
{
  while (1)
    {
      uint32_t idle;

      idle = lv_timer_handler();
      idle = idle ? idle : 1;
      usleep(idle * 1000);
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  lv_nuttx_dsc_t info;
  lv_nuttx_result_t result;
  lv_obj_t *scr;

  syslog(LOG_INFO, "Charging Station starting\n");

  lv_init();

  lv_nuttx_dsc_init(&info);

#ifdef CONFIG_LV_USE_NUTTX_LCD
