    }

  scr = lv_screen_active();
  lv_obj_set_style_bg_color(scr, lv_color_hex(0x1E1E2E), 0);

  /* Title */
  lv_obj_t *title = lv_label_create(scr);
  lv_label_set_text(title, "Charging Station - Touch Test");
  lv_obj_align(title, LV_ALIGN_TOP_MID, 0, 15);
  lv_obj_set_style_text_color(title, lv_color_hex(0xEEEEEE), 0);

  /* Big button in the center */
  g_btn = lv_button_create(scr);
  lv_obj_set_size(g_btn, 240, 120);
  lv_obj_align(g_btn, LV_ALIGN_CENTER, 0, -40);
  lv_obj_set_style_bg_color(g_btn, lv_color_hex(0x00B0FF), 0);
  lv_obj_set_style_radius(g_btn, 16, 0);
  lv_obj_add_event_cb(g_btn, btn_cb, LV_EVENT_PRESSED, NULL);
  lv_obj_add_event_cb(g_btn, btn_cb, LV_EVENT_RELEASED, NULL);

  lv_obj_t *btn_label = lv_label_create(g_btn);
  lv_label_set_text(btn_label, "Touch 0");
  lv_obj_center(btn_label);
  lv_obj_set_style_text_color(btn_label, lv_color_hex(0xFFFFFF), 0);
  lv_obj_set_style_text_font(btn_label, &lv_font_montserrat_20, 0);

  /* Coordinate display at the bottom */
  g_label_coord = lv_label_create(scr);
  lv_label_set_text(g_label_coord, "Touch the button!");
  lv_obj_align(g_label_coord, LV_ALIGN_BOTTOM_MID, 0, -30);
  lv_obj_set_style_text_color(g_label_coord, lv_color_hex(0x8E8E9E), 0);

  syslog(LOG_INFO, "Charging Station: display res=%ldx%ld\n",
         (long)lv_display_get_horizontal_resolution(result.disp),
         (long)lv_display_get_vertical_resolution(result.disp));

  if (result.indev)
    {
      syslog(LOG_INFO, "Charging Station: touchscreen registered\n");
    }
  else
    {
      syslog(LOG_WARNING, "Charging Station: no touchscreen (indev NULL)\n");
    }

  /* Enter the LVGL event loop */
  syslog(LOG_INFO, "Charging Station: entering poll loop\n");
  lv_nuttx_loop();

  lv_nuttx_deinit(&result);
  lv_deinit();
  return 0;
}

