/****************************************************************************
 * Contest 2026 team 008 - charging station UI (LVGL 9.x)
 *
 * 4-tab UI: Fast charge / Soldering station / Hot air gun / Settings
 * Uses fake data for now; real hardware data comes later.
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>

#include <lvgl/lvgl.h>

#include "charging_station_ui.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define SCREEN_W            480
#define SCREEN_H            272
#define NAV_H               40
#define TAB_H               (SCREEN_H - NAV_H)      /* 232 */

#define COLOR_BG            lv_color_hex(0x1E1E2E)
#define COLOR_CARD          lv_color_hex(0x2E2E3E)
#define COLOR_THEME         lv_color_hex(0x2563EB)
#define COLOR_OK            lv_color_hex(0x22C55E)
#define COLOR_WARN          lv_color_hex(0xF59E0B)
#define COLOR_ERR           lv_color_hex(0xEF4444)
#define COLOR_HEAT          lv_color_hex(0xEF4444)
#define COLOR_TEXT          lv_color_hex(0xEEEEEE)
#define COLOR_DIM           lv_color_hex(0x8E8E9E)
#define COLOR_BADGE_PD      lv_color_hex(0x2563EB)
#define COLOR_BADGE_QC      lv_color_hex(0x22C55E)
#define COLOR_BADGE_FCP     lv_color_hex(0xF59E0B)
#define COLOR_BADGE_AFC     lv_color_hex(0x8B5CF6)
#define COLOR_BADGE_IDLE    lv_color_hex(0x9CA3AF)

/* Fake data for the 4 charger channels */
typedef struct
{
  const char *name;
  const char *c_proto;     /* C port protocol */
  float       c_volt;
  float       c_amp;
  float       c_watt;
  const char *a_proto;     /* A port protocol */
  float       a_volt;
  float       a_amp;
  int         temp;
} chan_t;

static chan_t g_chan[4] =
{
  { "SW3538 #1", "PD", 20.0f, 2.5f, 50.0f, "IDLE", 0.0f, 0.0f, 45 },
  { "SW3538 #2", "PD", 12.0f, 1.8f, 21.6f, "QC",   9.0f, 1.5f, 38 },
  { "SW3538 #3", "IDLE", 0.0f, 0.0f, 0.0f, "FCP", 9.0f, 2.0f, 42 },
  { "SW3538 #4", "PD", 20.0f, 3.0f, 60.0f, "IDLE", 0.0f, 0.0f, 35 },
};

/* Tab1 widgets */
static lv_obj_t *g_lbl_input;
static lv_obj_t *g_lbl_bottom;
static lv_obj_t *g_chan_card[4];
static lv_obj_t *g_chan_c[4];
static lv_obj_t *g_chan_a[4];
static lv_obj_t *g_chan_temp[4];

/* Tab2 (soldering) widgets */
static lv_obj_t *g_lbl_iron_temp;
static lv_obj_t *g_lbl_iron_set;
static lv_obj_t *g_lbl_iron_status;
static lv_obj_t *g_lbl_iron_pwr;
static lv_chart_t *g_iron_chart;
static lv_chart_series_t *g_iron_series;
static lv_chart_series_t *g_iron_set_series;
static int g_iron_temp = 348;
static int g_iron_target = 350;
static bool g_iron_on = true;

/* Tab3 (hot air) widgets */
static lv_obj_t *g_lbl_hot_temp;
static lv_obj_t *g_lbl_hot_set;
static lv_obj_t *g_lbl_hot_status;
static lv_chart_t *g_hot_chart;
static lv_chart_series_t *g_hot_series;
static lv_chart_series_t *g_hot_pwr_series;
static int g_hot_temp = 295;
static int g_hot_target = 300;
static int g_hot_fan = 80;
static bool g_hot_on = true;

/* Tab4 settings */
static lv_obj_t *g_lbl_brightness;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static lv_color_t proto_color(const char *proto)
{
  if (strcmp(proto, "PD") == 0)  return COLOR_BADGE_PD;
  if (strcmp(proto, "QC") == 0)  return COLOR_BADGE_QC;
  if (strcmp(proto, "FCP") == 0) return COLOR_BADGE_FCP;
  if (strcmp(proto, "AFC") == 0) return COLOR_BADGE_AFC;
  return COLOR_BADGE_IDLE;
}

/****************************************************************************
 * Name: ui_build_tab1
 *
 * Fast charge page: status bar + 2x2 cards + bottom info bar
 ****************************************************************************/

static void ui_build_tab1(lv_obj_t *tab)
{
  lv_obj_t *lbl;
  int i;

  lv_obj_set_style_bg_color(tab, COLOR_BG, 0);

  /* Top status bar (32px) */
  lv_obj_t *bar = lv_obj_create(tab);
  lv_obj_set_size(bar, SCREEN_W, 32);
  lv_obj_set_pos(bar, 0, 0);
  lv_obj_set_style_bg_color(bar, COLOR_CARD, 0);
  lv_obj_set_style_border_width(bar, 0, 0);
  lv_obj_set_style_pad_all(bar, 4, 0);

  lbl = lv_label_create(bar);
  lv_label_set_text(lbl, "Charging Station");
  lv_obj_set_style_text_color(lbl, COLOR_TEXT, 0);

  g_lbl_input = lv_label_create(bar);
  lv_label_set_text(g_lbl_input, "24.0V 3.2A 76.8W  OK");
  lv_obj_align(g_lbl_input, LV_ALIGN_RIGHT_MID, -8, 0);
  lv_obj_set_style_text_color(g_lbl_input, COLOR_OK, 0);

  /* 2x2 card grid: 228x80 each, 8px gap */
  for (i = 0; i < 4; i++)
    {
      int cx = 8 + (i % 2) * (228 + 8);
      int cy = 40 + (i / 2) * (80 + 8);

      lv_obj_t *card = lv_obj_create(tab);
      lv_obj_set_size(card, 228, 80);
      lv_obj_set_pos(card, cx, cy);
      lv_obj_set_style_bg_color(card, COLOR_CARD, 0);
      lv_obj_set_style_radius(card, 8, 0);
      lv_obj_set_style_border_color(card, COLOR_DIM, 0);
      lv_obj_set_style_border_width(card, 1, 0);
      lv_obj_set_style_pad_all(card, 4, 0);
      g_chan_card[i] = card;

      /* Title: SW3538 #n */
      lbl = lv_label_create(card);
      lv_label_set_text(lbl, g_chan[i].name);
      lv_obj_set_style_text_color(lbl, COLOR_TEXT, 0);
      lv_obj_set_style_text_font(lbl, &lv_font_montserrat_12, 0);

      /* Temp top-right */
      g_chan_temp[i] = lv_label_create(card);
      lv_label_set_text_fmt(g_chan_temp[i], "T:%dC", g_chan[i].temp);
      lv_obj_align(g_chan_temp[i], LV_ALIGN_TOP_RIGHT, -4, 2);
      lv_obj_set_style_text_color(g_chan_temp[i], COLOR_DIM, 0);
      lv_obj_set_style_text_font(g_chan_temp[i], &lv_font_montserrat_10, 0);

      /* C port line */
      g_chan_c[i] = lv_label_create(card);
      lv_label_set_text(g_chan_c[i], "C: --");
      lv_obj_set_pos(g_chan_c[i], 4, 30);
      lv_obj_set_style_text_font(g_chan_c[i], &lv_font_montserrat_12, 0);

      /* A port line */
      g_chan_a[i] = lv_label_create(card);
      lv_label_set_text(g_chan_a[i], "A: --");
      lv_obj_set_pos(g_chan_a[i], 4, 52);
      lv_obj_set_style_text_font(g_chan_a[i], &lv_font_montserrat_12, 0);
    }

  /* Bottom info bar (32px at y=208) */
  lv_obj_t *bbar = lv_obj_create(tab);
  lv_obj_set_size(bbar, SCREEN_W, 32);
  lv_obj_set_pos(bbar, 0, 208);
  lv_obj_set_style_bg_color(bbar, COLOR_CARD, 0);
  lv_obj_set_style_border_width(bbar, 0, 0);
  lv_obj_set_style_pad_all(bbar, 4, 0);

  g_lbl_bottom = lv_label_create(bbar);
  lv_label_set_text(g_lbl_bottom, "Power: --W   Fault: none   Today: --kWh");
  lv_obj_set_style_text_color(g_lbl_bottom, COLOR_TEXT, 0);
  lv_obj_set_style_text_font(g_lbl_bottom, &lv_font_montserrat_12, 0);

  /* Initial refresh */
  ui_tab1_update();
}

/****************************************************************************
 * Name: ui_tab1_update
 *
 * Refresh tab1 with fake data
 ****************************************************************************/

void ui_tab1_update(void)
{
  int i;

  lv_label_set_text_fmt(g_lbl_input, "24.0V 3.2A 76.8W  OK");

  for (i = 0; i < 4; i++)
    {
      lv_color_t cc = proto_color(g_chan[i].c_proto);
      lv_color_t ac = proto_color(g_chan[i].a_proto);

      if (strcmp(g_chan[i].c_proto, "IDLE") == 0)
        {
          lv_label_set_text_fmt(g_chan_c[i], "C: IDLE");
          lv_obj_set_style_text_color(g_chan_c[i], COLOR_DIM, 0);
        }
      else
        {
          lv_label_set_text_fmt(g_chan_c[i], "C: %s %.1fV %.1fA %.1fW",
                                g_chan[i].c_proto,
                                g_chan[i].c_volt,
                                g_chan[i].c_amp,
                                g_chan[i].c_watt);
          lv_obj_set_style_text_color(g_chan_c[i], cc, 0);
        }

      if (strcmp(g_chan[i].a_proto, "IDLE") == 0)
        {
          lv_label_set_text_fmt(g_chan_a[i], "A: IDLE");
          lv_obj_set_style_text_color(g_chan_a[i], COLOR_DIM, 0);
        }
