                                g_chan[i].a_amp);
          lv_obj_set_style_text_color(g_chan_a[i], ac, 0);
        }

      lv_label_set_text_fmt(g_chan_temp[i], "T:%dC", g_chan[i].temp);
    }

  lv_label_set_text(g_lbl_bottom, "Power: 131.6W   Fault: none   Today: 1.2kWh");
}

/****************************************************************************
 * Name: ui_build_chart
 *
 * Build a rolling line chart with target line
 ****************************************************************************/

static void ui_build_chart(lv_obj_t *parent, lv_chart_t **chart_out,
                           lv_chart_series_t **series_out,
                           lv_chart_series_t **target_out,
                           lv_color_t line_color)
{
  lv_obj_t *chart = lv_chart_create(parent);
  lv_obj_set_size(chart, 464, 140);
  lv_obj_set_pos(chart, 8, 40);
  lv_chart_set_type(chart, LV_CHART_TYPE_LINE);
  lv_chart_set_point_count(chart, 60);
  lv_chart_set_range(chart, LV_CHART_AXIS_PRIMARY_Y, 0, 500);
  lv_chart_set_axis_tick(chart, LV_CHART_AXIS_PRIMARY_Y, 5, 0, 5, 2, true, 50);
  lv_chart_set_axis_tick(chart, LV_CHART_AXIS_PRIMARY_X, 5, 0, 10, 1, true, 30);
  lv_obj_set_style_bg_color(chart, COLOR_CARD, 0);

  *series_out = lv_chart_add_series(chart, line_color, LV_CHART_AXIS_PRIMARY_Y);
  *target_out = lv_chart_add_series(chart, COLOR_WARN, LV_CHART_AXIS_PRIMARY_Y);

  /* Pre-fill target line (dashed look via points) */
  int i;
  for (i = 0; i < 60; i++)
    {
      lv_chart_set_value_by_id(chart, *series_out, i, 0);
      lv_chart_set_value_by_id(chart, *target_out, i, 350);
    }

  *chart_out = (lv_chart_t *)chart;
}

