/****************************************************************************
 * Name: ui_sim_timer_cb
 *
 * Simulate data changes every 100ms
 ****************************************************************************/

static void ui_sim_timer_cb(lv_timer_t *timer)
{
  static int tick = 0;
  int i;

  tick++;

  /* Simulate channel 1 wattage fluctuation */
  g_chan[0].c_watt = 50.0f + (tick % 10) * 0.5f;
  g_chan[0].c_amp  = 2.5f + (tick % 5) * 0.1f;

  ui_tab1_update();

  /* Iron temp curve: random walk toward target */
  if (g_iron_on)
    {
      if (g_iron_temp < g_iron_target)
        g_iron_temp += 1;
      else if (g_iron_temp > g_iron_target)
        g_iron_temp -= 1;
    }
  else
    {
      if (g_iron_temp > 30)
        g_iron_temp -= 2;
    }

  if (tick % 10 == 0)
    {
      /* 1 point per second */
      lv_chart_set_next_value(g_iron_chart, g_iron_series, g_iron_temp);
      lv_chart_set_next_value(g_iron_chart, g_iron_set_series, g_iron_target);
      lv_chart_set_next_value(g_hot_chart, g_hot_series, g_hot_temp);
      lv_chart_set_next_value(g_hot_chart, g_hot_pwr_series,
                              g_hot_on ? 60 + (tick % 10) : 0);
    }

  lv_label_set_text_fmt(g_lbl_iron_status,
                        "Current: %dC  Power: 45%%  [%s]",
                        g_iron_temp, g_iron_on ? "HEATING" : "IDLE");
  lv_label_set_text_fmt(g_lbl_hot_status,
                        "Current: %dC  Pwr: 60%%  Fan: %d%%  [%s]",
                        g_hot_temp, g_hot_fan,
                        g_hot_on ? "HEATING" : "COOLING");
}

