 ****************************************************************************/

int cs_ui_init(lv_obj_t *scr)
{
  lv_obj_t *tv;
  lv_obj_t *tab;

  lv_obj_set_style_bg_color(scr, COLOR_BG, 0);

  /* Tabview fills the screen */
  tv = lv_tabview_create(scr);
  lv_obj_set_size(tv, SCREEN_W, SCREEN_H);
  lv_obj_set_pos(tv, 0, 0);
  lv_obj_set_style_bg_color(tv, COLOR_BG, 0);

  /* 4 tabs with English labels (no Chinese font needed) */
  tab = lv_tabview_add_tab(tv, "Charger");
  ui_build_tab1(tab);

  tab = lv_tabview_add_tab(tv, "Iron");
  ui_build_tab2(tab);

  tab = lv_tabview_add_tab(tv, "HotAir");
  ui_build_tab3(tab);

  tab = lv_tabview_add_tab(tv, "Settings");
  ui_build_tab4(tab);

  /* Data refresh + simulation timer (100ms) */
  lv_timer_create(ui_sim_timer_cb, 100, NULL);

  return 0;
}

