506	 * Name: ui_sim_timer_cb
507	 *
508	 * Simulate data changes every 100ms
509	 ****************************************************************************/
510	
511	static void ui_sim_timer_cb(lv_timer_t *timer)
512	{
513	  static int tick = 0;
514	  int i;
515	
516	  tick++;
517	
518	  /* Simulate channel 1 wattage fluctuation */
519	  g_chan[0].c_watt = 50.0f + (tick % 10) * 0.5f;
520	  g_chan[0].c_amp  = 2.5f + (tick % 5) * 0.1f;
521	
522	  ui_tab1_update();
523	
524	  /* Iron temp curve: random walk toward target */
525	  if (g_iron_on)
526	    {
527	      if (g_iron_temp < g_iron_target)
528	        g_iron_temp += 1;
529	      else if (g_iron_temp > g_iron_target)
530	        g_iron_temp -= 1;
531	    }
532	  else
533	    {
534	      if (g_iron_temp > 30)
535	        g_iron_temp -= 2;
536	    }
537	
538	  if (tick % 10 == 0)
539	    {
540	      /* 1 point per second */
541	      lv_chart_set_next_value(g_iron_chart, g_iron_series, g_iron_temp);
542	      lv_chart_set_next_value(g_iron_chart, g_iron_set_series, g_iron_target);
543	      lv_chart_set_next_value(g_hot_chart, g_hot_series, g_hot_temp);
544	      lv_chart_set_next_value(g_hot_chart, g_hot_pwr_series,
545	                              g_hot_on ? 60 + (tick % 10) : 0);
546	    }
547	
548	  lv_label_set_text_fmt(g_lbl_iron_status,
549	                        "Current: %dC  Power: 45%%  [%s]",
550	                        g_iron_temp, g_iron_on ? "HEATING" : "IDLE");
551	  lv_label_set_text_fmt(g_lbl_hot_status,
552	                        "Current: %dC  Pwr: 60%%  Fan: %d%%  [%s]",
553	                        g_hot_temp, g_hot_fan,
554	                        g_hot_on ? "HEATING" : "COOLING");
555	}
