/****************************************************************************
 * Name: ui_btn_cb
 *
 * Button event handler for Tab2/Tab3 controls
 ****************************************************************************/

static void ui_btn_cb(lv_event_t *e)
{
  const char *label = (const char *)lv_event_get_user_data(e);

  if (strcmp(label, "TEMP-") == 0)
    {
      if (g_iron_target > 100) g_iron_target -= 5;
    }
  else if (strcmp(label, "TEMP+") == 0)
    {
      if (g_iron_target < 480) g_iron_target += 5;
    }
  else if (strcmp(label, "TOGGLE") == 0)
    {
      g_iron_on = !g_iron_on;
    }
  else if (strcmp(label, "FAN-") == 0)
    {
      if (g_hot_fan > 0) g_hot_fan -= 10;
    }
  else if (strcmp(label, "FAN+") == 0)
    {
      if (g_hot_fan < 100) g_hot_fan += 10;
    }
  else if (strcmp(label, "HTOGGLE") == 0)
    {
      g_hot_on = !g_hot_on;
    }
}

/****************************************************************************
 * Name: ui_btn_make
 *
 * Create a button with an event callback
 ****************************************************************************/

static lv_obj_t *ui_btn_make(lv_obj_t *parent, const char *text,
                             const char *cb_label, int x, int w)
{
  lv_obj_t *btn = lv_button_create(parent);
  lv_obj_t *lbl;

  lv_obj_set_size(btn, w, 28);
  lv_obj_set_pos(btn, x, 0);
  lv_obj_set_style_bg_color(btn, COLOR_CARD, 0);
  lv_obj_add_event_cb(btn, ui_btn_cb, LV_EVENT_CLICKED, (void *)cb_label);

  lbl = lv_label_create(btn);
  lv_label_set_text(lbl, text);
  lv_obj_center(lbl);
  lv_obj_set_style_text_color(lbl, COLOR_TEXT, 0);
  lv_obj_set_style_text_font(lbl, &lv_font_montserrat_14, 0);

  return btn;
}

