/****************************************************************************
 * Name: ui_iron_arc_cb
 *
 * Temperature arc (rotary) change callback. Clockwise increases temp.
 ****************************************************************************/

static void ui_iron_arc_cb(lv_event_t *e)
{
  lv_obj_t *arc = lv_event_get_target(e);
  int val = (int)lv_arc_get_value(arc);
  int target = IRON_TEMP_MIN + val;

  /* Snap to 5C steps */
  target = ((target + IRON_TEMP_STEP / 2) / IRON_TEMP_STEP) * IRON_TEMP_STEP;
  if (target > IRON_TEMP_MAX) target = IRON_TEMP_MAX;
  if (target < IRON_TEMP_MIN) target = IRON_TEMP_MIN;

  g_iron_target = target;
  lv_label_set_text_fmt(g_iron_arc_lbl, "%d", target);
  lv_arc_set_value(arc, target - IRON_TEMP_MIN);
}

