/****************************************************************************
 * Name: ui_command_execute
 *
 * Parse a command string and execute it on the simulated device.
 ****************************************************************************/

static void ui_command_execute(const char *cmd)
{
  char buf[64];
  int temp;

  /* Normalize: lowercase, trim spaces */
  strncpy(buf, cmd, sizeof(buf) - 1);
  buf[sizeof(buf) - 1] = '\0';

  /* Remove common prefixes: "hi vela" / "hello" / "set" etc */
  if (strstr(buf, "iron") != NULL || strstr(buf, "temp") != NULL)
    {
      /* Extract temperature value via sscanf on digits */
      char *p = buf;
      int found = 0;
      while (*p)
        {
          if (*p >= '0' && *p <= '9')
            {
              temp = atoi(p);
              /* validate range */
              if (temp >= IRON_TEMP_MIN && temp <= IRON_TEMP_MAX)
                {
                  g_iron_target = temp;
                  lv_label_set_text_fmt(g_iron_arc_lbl, "%d", temp);
                  lv_arc_set_value(g_iron_arc, temp - IRON_TEMP_MIN);
                  lv_label_set_text_fmt(g_ai_chat_lbl,
                                        "Iron temp set to %dC", temp);
                  found = 1;
                }
              break;
            }
          p++;
        }
      if (!found)
        {
          lv_label_set_text(g_ai_chat_lbl, "I need a temp value");
        }
    }
  else if (strstr(buf, "on") != NULL || strstr(buf, "heat") != NULL)
    {
      g_iron_on = true;
      lv_label_set_text(g_ai_chat_lbl, "Iron heating ON");
    }
  else if (strstr(buf, "off") != NULL || strstr(buf, "stop") != NULL)
    {
      g_iron_on = false;
      lv_label_set_text(g_ai_chat_lbl, "Iron OFF");
    }
  else if (strstr(buf, "hello") != NULL || strstr(buf, "hi") != NULL)
    {
      lv_label_set_text(g_ai_chat_lbl, "Hello! I can set the iron temp.");
    }
  else
    {
      lv_label_set_text(g_ai_chat_lbl, "Sorry, not understood");
    }
}

