/****************************************************************************
 * Name: cs_ui_data_tick
 *
 * Simulate data changes. Called periodically.
 ****************************************************************************/

void cs_ui_data_tick(void)
{
  static int tick = 0;
  int i;

  tick++;

  /* Clock: advance 1 min every 60 ticks (tick = 1s) */
  g_clock_min++;
  if (g_clock_min >= 60)
    {
      g_clock_min = 0;
      g_clock_hour = (g_clock_hour + 1) % 24;
    }

  lv_label_set_text_fmt(g_lbl_time, "%02d:%02d", g_clock_hour, g_clock_min);
  lv_label_set_text_fmt(g_info_clock_lbl, "%02d:%02d", g_clock_hour, g_clock_min);

  /* Update charger ports with simulated fluctuation */
  for (i = 0; i < 4; i++)
    {
      if (strcmp(g_chan[i].c_proto, "IDLE") != 0)
        {
          g_chan[i].c_amp  = 2.0f + (float)((tick + i) % 20) * 0.05f;
          g_chan[i].c_watt = g_chan[i].c_volt * g_chan[i].c_amp;
          lv_label_set_text_fmt(g_chan_c_lbl[i],
                                "C %s %.1fV %.2fA %.1fW",
                                g_chan[i].c_proto, g_chan[i].c_volt,
                                g_chan[i].c_amp, g_chan[i].c_watt);
        }
      else
        {
          lv_label_set_text_fmt(g_chan_c_lbl[i], "C %s --", g_chan[i].c_proto);
        }

      if (strcmp(g_chan[i].a_proto, "IDLE") != 0)
        {
          g_chan[i].a_amp  = 1.0f + (float)((tick + i * 3) % 15) * 0.05f;
          g_chan[i].a_watt = g_chan[i].a_volt * g_chan[i].a_amp;
          lv_label_set_text_fmt(g_chan_a_lbl[i],
                                "A %s %.1fV %.2fA %.1fW",
                                g_chan[i].a_proto, g_chan[i].a_volt,
                                g_chan[i].a_amp, g_chan[i].a_watt);
        }
      else
        {
          lv_label_set_text_fmt(g_chan_a_lbl[i], "A %s --", g_chan[i].a_proto);
        }
    }

  /* Iron temp: PID-like approach to target */
  if (g_iron_on)
    {
      int err = g_iron_target - g_iron_temp;
      if (err > 0) g_iron_temp += (err > 10) ? 2 : 1;
      else if (err < 0) g_iron_temp += (err < -10) ? -2 : -1;
      g_iron_power = 20 + abs(err) * 2;
      if (g_iron_power > 100) g_iron_power = 100;
    }
  else
    {
      if (g_iron_temp > 30) g_iron_temp -= 1;
      g_iron_power = 0;
    }

  lv_label_set_text_fmt(g_iron_temp_lbl, "%dC", g_iron_temp);
  lv_label_set_text_fmt(g_iron_pwr_lbl, "%dW", g_iron_power);
  lv_label_set_text_fmt(g_iron_status_lbl, "Target %dC  [%s]",
                        g_iron_target, g_iron_on ? "ON" : "OFF");

  /* Only update arc label if changed (avoid redundant redraw) */
  if (g_arc_last_temp != g_iron_temp)
    {
      g_arc_last_temp = g_iron_temp;
      lv_label_set_text_fmt(g_iron_arc_lbl, "%d", g_iron_target);
    }

  /* Append chart points once per second (10 ticks at 100ms) */
  if (tick % 10 == 0)
    {
      lv_chart_set_next_value(g_iron_chart, g_iron_temp_ser, g_iron_temp);
      lv_chart_set_next_value(g_iron_chart, g_iron_pwr_ser, g_iron_power);
    }
}

