/****************************************************************************
 * Contest 2026 team 008 - SW3538 fast-charge chip driver (NuttX)
 *
 * SW3538: PD/QC multi-protocol dual-port charger controller.
 *  - I2C slave address: 0x3C (7-bit)
 *  - Register address: single byte
 *  - ADC: write Reg0x40 to select channel, read Reg0x41(low) + Reg0x42(high)
 *
 * This driver only READS registers (VOUT / currents / protocol).
 * Writing config is not needed for monitoring.
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <debug.h>

#include <nuttx/i2c/i2c_master.h>
#include <arch/board/board.h>

#include "sw3538.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define SW3538_ADDR         0x3C   /* 7-bit slave address */
#define SW3538_FREQ         100000 /* 100 kHz */

/* Registers */
#define SW3538_REG_PROTO    0x09   /* Fast-charge protocol indicator */
#define SW3538_REG_ADC_SEL  0x40   /* ADC channel select (R/W) */
#define SW3538_REG_ADC_LO   0x41   /* ADC result low 8 bits (R) */
#define SW3538_REG_ADC_HI   0x42   /* ADC result high bits (R) */

/* ADC channels (Reg0x40 value) */
#define ADC_CH_IA           1      /* Path1 current (C port) 2.5mA/bit @5mohm */
#define ADC_CH_IC           2      /* Path2 current (A port) 2.5mA/bit @5mohm */
#define ADC_CH_VOUT         5      /* Output voltage 6mV/bit */
#define ADC_CH_VOUT_CONV    11     /* Converted output voltage 1mV/bit */
#define ADC_CH_NTC          7      /* NTC voltage 1.2mV/bit */

#define ADC_LO_BITS         8      /* wait for ADC conversion */

/****************************************************************************
 * Private Data
 ****************************************************************************/

static FAR struct i2c_master_s *g_i2c;
static struct sw3538_status_s g_status;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: sw3538_read_regs
 *
 * Read len bytes from a register. Format:
 *   [S] [0x3C w] [reg] [Sr] [0x3C r] [data...] [P]
 ****************************************************************************/

static int sw3538_read_regs(uint8_t reg, uint8_t *buf, int len)
{
  struct i2c_msg_s msg[2];
  uint8_t regaddr = reg;
  int ret;

  if (g_i2c == NULL)
    {
      return -ENODEV;
    }

  msg[0].frequency = SW3538_FREQ;
  msg[0].addr      = SW3538_ADDR;
  msg[0].flags     = 0;              /* Write register address */
  msg[0].buffer    = &regaddr;
  msg[0].length    = 1;

  msg[1].frequency = SW3538_FREQ;
  msg[1].addr      = SW3538_ADDR;
  msg[1].flags     = I2C_M_READ;     /* Read data */
  msg[1].buffer    = buf;
  msg[1].length    = len;

  ret = I2C_TRANSFER(g_i2c, msg, 2);
  return ret;
}

/****************************************************************************
 * Name: sw3538_write_reg
 *
 * Write one byte to a register.
 ****************************************************************************/

static int sw3538_write_reg(uint8_t reg, uint8_t val)
{
  struct i2c_msg_s msg;
  uint8_t tx[2];
  int ret;

  if (g_i2c == NULL)
    {
      return -ENODEV;
    }

  tx[0] = reg;
  tx[1] = val;

  msg.frequency = SW3538_FREQ;
  msg.addr      = SW3538_ADDR;
  msg.flags     = 0;
  msg.buffer    = tx;
  msg.length    = 2;

  ret = I2C_TRANSFER(g_i2c, &msg, 1);
  return ret;
}

/****************************************************************************
 * Name: sw3538_adc_code
 *
 * Select an ADC channel and read the 12-bit code from 0x41/0x42.
 ****************************************************************************/

static uint32_t sw3538_adc_code(uint8_t channel)
{
  uint8_t lo = 0;
  uint8_t hi = 0;
  int ret;

  /* Select channel */
  ret = sw3538_write_reg(SW3538_REG_ADC_SEL, channel);
  if (ret < 0)
    {
      return 0;
    }

  /* Wait for ADC conversion (channel select latches 0x41/0x42) */
  up_udelay(5000);

  /* Read result */
  if (sw3538_read_regs(SW3538_REG_ADC_LO, &lo, 1) < 0)
    {
      return 0;
    }

  if (sw3538_read_regs(SW3538_REG_ADC_HI, &hi, 1) < 0)
    {
      return 0;
    }

  /* 12-bit: hi[3:0] << 8 | lo */
  return (((uint32_t)(hi & 0x0F)) << 8) | lo;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: sw3538_init
 *
 * Bind to an I2C bus and do a quick link probe.
 ****************************************************************************/

int sw3538_init(int bus)
{
  uint8_t proto;

  if (bus < 0)
    {
      bus = 0;
    }

  g_i2c = stm32_i2cbus_initialize(bus);
  if (g_i2c == NULL)
    {
      ierr("SW3538: failed to init I2C bus %d\n", bus);
      return -ENODEV;
    }

  memset(&g_status, 0, sizeof(g_status));

  /* Link probe: read protocol register */
  if (sw3538_read_regs(SW3538_REG_PROTO, &proto, 1) < 0)
    {
      ierr("SW3538: no ACK from device at 0x%02x (check pin21 PSET pull-up)\n",
           SW3538_ADDR);
      return -ENXIO;
    }

  iinfo("SW3538: found at 0x%02x on bus %d\n", SW3538_ADDR, bus);
  return OK;
}

/****************************************************************************
 * Name: sw3538_read_status
 *
 * Read output voltage (V), C/A currents (A) and fast-charge protocol.
 * Returns 0 on success, negative errno on failure.
 ****************************************************************************/

int sw3538_read_status(FAR struct sw3538_status_s *st)
{
  uint32_t code;
  uint8_t proto = 0;
  int ret;

  if (st == NULL)
    {
      return -EINVAL;
    }

  /* Protocol register also acts as link probe */
  ret = sw3538_read_regs(SW3538_REG_PROTO, &proto, 1);
  if (ret < 0)
    {
      return ret;
    }

  /* Output voltage (VOUT, 6mV/bit) */
  code = sw3538_adc_code(ADC_CH_VOUT);
  g_status.vout_mv = (uint16_t)(code * 6u);

  /* C port current (2.5mA/bit) */
  code = sw3538_adc_code(ADC_CH_IC);
  g_status.ic_ma = (uint16_t)(code * 25u / 10u);

  /* A port current (2.5mA/bit) */
  code = sw3538_adc_code(ADC_CH_IA);
  g_status.ia_ma = (uint16_t)(code * 25u / 10u);

  /* Fast-charge protocol: bits3-0 of Reg0x09 */
  g_status.proto = proto & 0x0F;

  *st = g_status;
  return OK;
}

/****************************************************************************
 * Name: sw3538_proto_name
 *
 * Return a human-readable protocol name.
 ****************************************************************************/

const char *sw3538_proto_name(uint8_t proto)
{
  switch (proto)
    {
      case 0:  return "NONE";
      case 1:  return "QC2.0";
      case 2:  return "QC3.0";
      case 3:  return "QC3+";
      case 4:  return "FCP";
      case 5:  return "SCP";
      case 6:  return "PD";
      case 7:  return "PD-PPS";
      case 8:  return "PE1.1";
      case 9:  return "PE2.0";
      case 10: return "VOOC1";
      case 11: return "VOOC4";
      case 13: return "SFCP";
      case 14: return "AFC";
      case 15: return "TFCP";
      default: return "?";
    }
}

