/****************************************************************************
 * Contest 2026 team 008 - charging station main
 *
 * Entry point: initializes LVGL, display and touchscreen, then
 * enters the LVGL event loop with the charging station UI.
 * Reads SW3538 (I2C4) for real channel-1 data every ~500ms.
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>

#include <lvgl/lvgl.h>

#include "charging_station_ui.h"
#include "sw3538.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define SW3538_I2C_BUS      4    /* I2C4 (D14=SDA/PD13, D15=SCL/PD12) */

/****************************************************************************
 * Private Data
 ****************************************************************************/

static bool g_sw3538_ok = false;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: sw3538_poll
 *
 * Read SW3538 and push real data into UI channel 1.
 * On failure, mark channel idle but keep the app running.
 ****************************************************************************/

static void sw3538_poll(void)
{
  struct sw3538_status_s st;
  int ret;

  if (!g_sw3538_ok)
    {
      return;
    }

  ret = sw3538_read_status(&st);
  if (ret < 0)
    {
      /* I2C glitch during charging - keep last display, just mark once */
      cs_ui_set_ch1_online(false);
      return;
    }

  /* Feed UI: C port voltage/current, protocol string */
  cs_ui_set_ch1_real((float)st.vout_mv / 1000.0f,
                     (float)st.ic_ma / 1000.0f,
                     sw3538_proto_name(st.proto));
}

/****************************************************************************
 * Name: data_timer_cb
 *
 * Periodically refresh simulated data + real SW3538 readings.
 ****************************************************************************/

static void data_timer_cb(lv_timer_t *timer)
{
  static int slow = 0;

  cs_ui_data_tick();

  /* SW3538 read every 5 ticks (~500ms): 3 ADC conversions take time */
  if (++slow >= 5)
    {
      slow = 0;
      sw3538_poll();
    }

  (void)timer;
}

/****************************************************************************
 * Name: lv_nuttx_loop
 *
 * Standard LVGL poll loop.
 ****************************************************************************/

static void lv_nuttx_loop(void)
{
  while (1)
    {
      uint32_t idle;

      idle = lv_timer_handler();
      idle = idle ? idle : 1;
      usleep(idle * 1000);
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  lv_nuttx_dsc_t info;
  lv_nuttx_result_t result;

  syslog(LOG_INFO, "Charging Station starting\n");

  /* Init SW3538 on I2C4 (non-fatal: UI runs on simulated data if absent) */
  if (sw3538_init(SW3538_I2C_BUS) < 0)
    {
      syslog(LOG_WARNING, "Charging Station: SW3538 not detected, "
             "channel 1 stays simulated\n");
    }
  else
    {
      g_sw3538_ok = true;
      syslog(LOG_INFO, "Charging Station: SW3538 ready on I2C4\n");
    }

  lv_init();

  lv_nuttx_dsc_init(&info);

#ifdef CONFIG_LV_USE_NUTTX_LCD
  info.fb_path = "/dev/lcd0";
#endif

  lv_nuttx_init(&info, &result);

  if (result.disp == NULL)
    {
      syslog(LOG_ERR, "Charging Station: display init failed\n");
      lv_deinit();
      return -1;
    }

  /* Build the charging station UI */
  if (cs_ui_init(lv_screen_active()) < 0)
    {
      syslog(LOG_ERR, "Charging Station: UI init failed\n");
      lv_nuttx_deinit(&result);
      lv_deinit();
      return -1;
    }

  /* Start data simulation timer (100ms) */
  lv_timer_create(data_timer_cb, 100, NULL);

  syslog(LOG_INFO, "Charging Station: display res=%ldx%ld\n",
         (long)lv_display_get_horizontal_resolution(result.disp),
         (long)lv_display_get_vertical_resolution(result.disp));

  if (result.indev)
    {
      /* Speed up touch reading: 20ms poll period (faster response) */
      lv_indev_set_mode(result.indev, LV_INDEV_MODE_TIMER);
      lv_timer_t *t = lv_indev_get_read_timer(result.indev);
      if (t)
        {
          lv_timer_set_period(t, 20);
        }
      syslog(LOG_INFO, "Charging Station: touchscreen registered (20ms poll)\n");
    }
  else
    {
      syslog(LOG_WARNING, "Charging Station: no touchscreen (indev NULL)\n");
    }

  /* Enter the LVGL event loop */
  syslog(LOG_INFO, "Charging Station: entering poll loop\n");
  lv_nuttx_loop();

  lv_nuttx_deinit(&result);
  lv_deinit();
  return 0;
}

