input.new_string:
 * Name: ui_build_charger
 *
 * Tab1: 4 channels x (C port + A port) = 8 ports, each showing V/A/W.
 * 2x2 card grid.
 ****************************************************************************/

static void ui_build_charger(lv_obj_t *parent)
{
  lv_obj_t *lbl;
  int i;

  /* Input summary line */
  g_input_lbl = lv_label_create(parent);
  lv_label_set_text(g_input_lbl, "SW3538 Monitor");
  lv_obj_set_pos(g_input_lbl, 8, 4);
  lv_obj_set_style_text_color(g_input_lbl, COLOR_DIM, 0);
  lv_obj_set_style_text_font(g_input_lbl, &lv_font_montserrat_14, 0);

  /* 2x2 card grid: card 228x92, gap 8, start y=28 */
  for (i = 0; i < 4; i++)
    {
      int cx = 8 + (i % 2) * (228 + 8);
      int cy = 28 + (i / 2) * (92 + 8);

      /* Card container */
      lv_obj_t *card = lv_obj_create(parent);
      lv_obj_set_size(card, 228, 92);
      lv_obj_set_pos(card, cx, cy);
      lv_obj_set_style_bg_color(card, COLOR_CARD, 0);
      lv_obj_set_style_radius(card, 10, 0);
      lv_obj_set_style_border_color(card, COLOR_CARD2, 0);
      lv_obj_set_style_border_width(card, 1, 0);
      lv_obj_set_style_pad_all(card, 6, 0);

      /* Channel name */
      lbl = lv_label_create(card);
      lv_label_set_text(lbl, g_chan[i].name);
      lv_obj_set_pos(lbl, 6, 2);
      lv_obj_set_style_text_color(lbl, COLOR_TEXT, 0);
      lv_obj_set_style_text_font(lbl, &lv_font_montserrat_14, 0);

      /* C port label */
      g_chan_c_lbl[i] = lv_label_create(card);
      lv_label_set_text(g_chan_c_lbl[i], "C --");
      lv_obj_set_pos(g_chan_c_lbl[i], 6, 26);
      lv_obj_set_style_text_font(g_chan_c_lbl[i], &lv_font_montserrat_14, 0);

      /* A port label */
      g_chan_a_lbl[i] = lv_label_create(card);
      lv_label_set_text(g_chan_a_lbl[i], "A --");
      lv_obj_set_pos(g_chan_a_lbl[i], 6, 50);
      lv_obj_set_style_text_font(g_chan_a_lbl[i], &lv_font_montserrat_14, 0);

      /* Die temp top-right */
      lbl = lv_label_create(card);
      lv_label_set_text_fmt(lbl, "%dC", g_chan[i].die_temp);
      lv_obj_align(lbl, LV_ALIGN_TOP_RIGHT, -6, 4);
      lv_obj_set_style_text_color(lbl, COLOR_DIM, 0);
      lv_obj_set_style_text_font(lbl, &lv_font_montserrat_14, 0);
    }
}

