static void ui_build_charger(lv_obj_t *parent)
{
  lv_obj_t *lbl;
  int i;
  lv_coord_t avail_w = lv_obj_get_width(parent);
  lv_coord_t avail_h = lv_obj_get_height(parent);
  int gap   = 8;
  int card_w;
  int card_h;
  int start_y;

  /* Compact 2x2 grid computed from the ACTUAL tab content area,
   * so it fits without scrolling regardless of tab-bar height. */
  card_w = (avail_w - 3 * gap) / 2;
  card_h = (avail_h - 3 * gap) / 2;
  if (card_w < 100) card_w = 100;
  if (card_h < 60)  card_h = 60;

  /* Small title in the top-left of the first card is skipped; put a
   * thin header only if room permits (height > 2 cards + header). */
  start_y = 4;

  /* Optional compact header */
  g_input_lbl = lv_label_create(parent);
  lv_label_set_text(g_input_lbl, "SW3538 Monitor");
  lv_obj_set_pos(g_input_lbl, 10, 2);
  lv_obj_set_style_text_color(g_input_lbl, COLOR_DIM, 0);
  lv_obj_set_style_text_font(g_input_lbl, &lv_font_montserrat_14, 0);

  /* If the header pushes cards off-screen, shrink card height */
  if (start_y + 18 + card_h * 2 + gap > avail_h)
    {
      card_h = (avail_h - 18 - 2 * gap) / 2;
    }

  for (i = 0; i < 4; i++)
    {
      int cx = gap + (i % 2) * (card_w + gap);
      int cy = start_y + 18 + (i / 2) * (card_h + gap);

      /* Card container */
      lv_obj_t *card = lv_obj_create(parent);
      lv_obj_set_size(card, card_w, card_h);
