void cs_ui_set_ch1_ports(float c_volt, float c_amp,
                         float a_volt, float a_amp,
                         const char *proto)
{
  static char ch1_proto[8] = "PD";

  if (proto != NULL)
    {
      snprintf(ch1_proto, sizeof(ch1_proto), "%s", proto);
    }

  /* C port */
  if (c_amp > 0.01f)
    {
      g_chan[0].c_proto = ch1_proto;
      g_chan[0].c_volt  = c_volt;
      g_chan[0].c_amp   = c_amp;
      g_chan[0].c_watt  = c_volt * c_amp;
    }
  else
    {
      g_chan[0].c_proto = "IDLE";
      g_chan[0].c_volt  = 0.0f;
      g_chan[0].c_amp   = 0.0f;
      g_chan[0].c_watt  = 0.0f;
    }

  /* A port */
  if (a_amp > 0.01f)
    {
      g_chan[0].a_proto = ch1_proto;
      g_chan[0].a_volt  = a_volt;
      g_chan[0].a_amp   = a_amp;
      g_chan[0].a_watt  = a_volt * a_amp;
    }
  else
    {
      g_chan[0].a_proto = "IDLE";
      g_chan[0].a_volt  = 0.0f;
      g_chan[0].a_amp   = 0.0f;
      g_chan[0].a_watt  = 0.0f;
    }
}

