/****************************************************************************
 * Contest 2026 team 008 - soldering iron module
 *
 * MAX6675 (K-thermocouple, software SPI) + software PWM heater + PID.
 * All GPIO based, no public-tree config changes needed.
 ****************************************************************************/

#ifndef __IRON_H
#define __IRON_H

#include <stdbool.h>
#include <stdint.h>

/****************************************************************************
 * Public Types
 ****************************************************************************/

struct iron_status_s
{
  int   temp_c;       /* Current tip temperature in C (from MAX6675) */
  int   target_c;     /* Target temperature */
  float power_pct;    /* Current PWM output 0..100 */
  bool  heating;      /* Heater enabled */
  bool  sensor_ok;    /* MAX6675 communication / thermocouple OK */
};

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

/* Initialize GPIO pins for MAX6675 + heater. Returns 0 on success. */
int iron_init(void);

/* Periodic tick (call every ~100ms): read temp + run PID + update PWM */
void iron_tick(void);

/* Control */
void iron_set_target(int temp_c);
void iron_set_heater(bool on);
void iron_set_pid(float p, float i, float d);

/* Query */
void iron_get_status(FAR struct iron_status_s *st);

#endif /* __IRON_H */

/****************************************************************************
 * Contest 2026 team 008 - soldering iron module
 *
 * MAX6675 K-thermocouple reader over software SPI (bit-bang GPIO),
 * software PWM heater control and a simple PID loop.
 *
 * Wiring (Arduino headers):
 *   MAX6675 SCK -> D8  (PE3)
 *   MAX6675 CS  -> D7  (PI8)
 *   MAX6675 SO  -> D6  (PE6)
 *   Heater PWM  -> D4  (PK1) -> NPN transistor -> MOSFET -> 24V iron
 *
 * MAX6675 protocol (16-bit read):
 *   D15=0(dummy), D14-D3=temp(12bit, 0.25C/bit),
 *   D2=1 thermocouple open, D1=0, D0=tri-state
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <debug.h>

#include <nuttx/arch.h>
#include <arch/board/board.h>
#include <arch/chip/chip.h>

#include "stm32_gpio.h"
#include "iron.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* --- GPIO pin assignments (Arduino D4/D6/D7/D8) --- */

#define IRON_GPIO_SCK    (GPIO_OUTPUT | GPIO_PUSHPULL | GPIO_SPEED_50MHz | \
                          GPIO_OUTPUT_CLEAR | GPIO_PORTE | GPIO_PIN3)   /* D8 */
#define IRON_GPIO_CS     (GPIO_OUTPUT | GPIO_PUSHPULL | GPIO_SPEED_50MHz | \
                          GPIO_OUTPUT_SET   | GPIO_PORTI | GPIO_PIN8)   /* D7 */
#define IRON_GPIO_SO     (GPIO_INPUT  | GPIO_FLOAT | GPIO_PORTE | GPIO_PIN6) /* D6 */
#define IRON_GPIO_HEAT   (GPIO_OUTPUT | GPIO_PUSHPULL | GPIO_SPEED_50MHz | \
                          GPIO_OUTPUT_CLEAR | GPIO_PORTK | GPIO_PIN1)   /* D4 */

/* --- Timing (us) --- */
#define IRON_SPI_HALF_PERIOD_US  2    /* ~250kHz bit clock */
#define IRON_TICK_MS             100  /* PID period */

/* --- PID limits --- */
#define IRON_TEMP_MIN     100
#define IRON_TEMP_MAX     480
#define IRON_PWR_MAX      100.0f

/* PWM period in ticks (software PWM at ~1kHz => 1ms period) */
#define IRON_PWM_PERIOD_MS   1
#define IRON_PWM_TICKS       10   /* 100ms tick / 1ms period = 10 slices */

/****************************************************************************
 * Private Data
 ****************************************************************************/

static int   g_temp_raw    = 0;   /* last ADC code */
static float g_temp_c      = 25.0f;
static int   g_target_c    = 350;
static bool  g_heating     = false;
static bool  g_sensor_ok   = false;
static float g_kp          = 3.0f;
static float g_ki          = 0.05f;
static float g_kd          = 1.5f;
static float g_power       = 0.0f;   /* 0..100 */

/* PID state */
static float g_integral    = 0.0f;
static float g_last_error  = 0.0f;

/* Software PWM state: counts down every tick */
static int   g_pwm_slice   = 0;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: iron_spi_delay
 ****************************************************************************/

static inline void iron_spi_delay(void)
{
  up_udelay(IRON_SPI_HALF_PERIOD_US);
}

/****************************************************************************
 * Name: max6675_read
 *
 * Bit-bang a 16-bit read from the MAX6675.
 * Returns 16-bit raw value (D2 = thermocouple open flag).
 ****************************************************************************/

static uint16_t max6675_read(void)
{
  uint16_t value = 0;
  int i;

  /* CS low to start */
  stm32_gpiowrite(IRON_GPIO_CS, false);
  iron_spi_delay();

  /* Read 16 bits, MSB first, sample on rising edge */
  for (i = 0; i < 16; i++)
    {
      /* SCK low -> data valid to read */
      stm32_gpiowrite(IRON_GPIO_SCK, false);
      iron_spi_delay();

      /* Sample SO on rising edge per MAX6675: data changes on falling
       * edge, so read while clock is low (stable). */
      value = (value << 1);
      if (stm32_gpioread(IRON_GPIO_SO))
        {
          value |= 1;
        }

      /* SCK high */
      stm32_gpiowrite(IRON_GPIO_SCK, true);
      iron_spi_delay();
    }

  /* CS high to end */
  stm32_gpiowrite(IRON_GPIO_CS, true);
  iron_spi_delay();

  return value;
}

/****************************************************************************
 * Name: max6675_temp
 *
 * Decode 16-bit read into Celsius. Returns -1000 if thermocouple open.
 ****************************************************************************/

static float max6675_temp(uint16_t raw)
{
  if (raw & 0x0004)         /* D2: thermocouple open */
    {
      return -1000.0f;
    }

  /* D14-D3 = 12-bit value, 0.25 C/bit */
  return (float)((raw >> 3) & 0x0FFF) * 0.25f;
}

/****************************************************************************
 * Name: iron_pid_update
 *
 * Compute heater power % from PID on temperature error.
 ****************************************************************************/

static void iron_pid_update(void)
{
  float error;
  float p_term;
  float i_term;
  float d_term;
  float dt_sec;

  if (!g_heating || !g_sensor_ok)
    {
      g_power = 0.0f;
      g_integral = 0.0f;
      g_last_error = 0.0f;
      return;
    }

  error    = (float)(g_target_c) - g_temp_c;
  dt_sec   = IRON_TICK_MS / 1000.0f;

  /* Proportional */
  p_term = g_kp * error;

  /* Integral with anti-windup */
  g_integral += error * dt_sec;
  if (g_integral >  1000.0f) g_integral =  1000.0f;
  if (g_integral < -1000.0f) g_integral = -1000.0f;
  i_term = g_ki * g_integral;

  /* Derivative */
  d_term = g_kd * (error - g_last_error) / dt_sec;

  g_last_error = error;

  /* Sum and clamp 0..100 */
  g_power = p_term + i_term + d_term;
  if (g_power < 0.0f)   g_power = 0.0f;
  if (g_power > IRON_PWR_MAX) g_power = IRON_PWR_MAX;
}

/****************************************************************************
 * Name: iron_pwm_apply
 *
 * Software PWM: turn heater GPIO on/off based on power %.
 * Called once per tick (100ms). We split the 100ms into N slices and
 * keep the heater on for the first (power%) slices.
 ****************************************************************************/

static void iron_pwm_apply(void)
{
  int on_slices = (int)(g_power / 100.0f * IRON_PWM_TICKS);

  if (!g_heating || on_slices <= 0)
    {
      stm32_gpiowrite(IRON_GPIO_HEAT, false);
      return;
    }

  if (on_slices >= IRON_PWM_TICKS)
    {
      stm32_gpiowrite(IRON_GPIO_HEAT, true);
      return;
    }

  /* Cycle through slices */
  g_pwm_slice++;
  if (g_pwm_slice >= IRON_PWM_TICKS)
    {
      g_pwm_slice = 0;
    }

  stm32_gpiowrite(IRON_GPIO_HEAT, g_pwm_slice < on_slices);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int iron_init(void)
{
  /* Configure GPIO pins */
  stm32_configgpio(IRON_GPIO_SCK);
  stm32_configgpio(IRON_GPIO_CS);
  stm32_configgpio(IRON_GPIO_SO);
  stm32_configgpio(IRON_GPIO_HEAT);

  /* Idle states: CS high, clock low, heater off */
  stm32_gpiowrite(IRON_GPIO_CS, true);
  stm32_gpiowrite(IRON_GPIO_SCK, false);
  stm32_gpiowrite(IRON_GPIO_HEAT, false);

  /* Probe MAX6675 */
  {
    uint16_t raw = max6675_read();
    float t = max6675_temp(raw);

    if (t < -900.0f)
      {
        iwarn("IRON: thermocouple open (raw=0x%04x)\n", raw);
        g_sensor_ok = false;
      }
    else
      {
        g_temp_c = t;
        g_sensor_ok = true;
        iinfo("IRON: MAX6675 ok, T=%.1fC (raw=0x%04x)\n", t, raw);
      }
  }

  return 0;
}

void iron_tick(void)
{
  uint16_t raw;
  float t;

  /* Read temperature */
  raw = max6675_read();
  t = max6675_temp(raw);

  if (t < -900.0f)
    {
      g_sensor_ok = false;
      g_power = 0.0f;         /* Safety: no sensor, no heat */
      stm32_gpiowrite(IRON_GPIO_HEAT, false);
    }
  else
    {
      g_sensor_ok = true;
      g_temp_c = t;
    }

  /* Run PID */
  iron_pid_update();

  /* Apply PWM */
  iron_pwm_apply();
}

void iron_set_target(int temp_c)
{
  if (temp_c < IRON_TEMP_MIN) temp_c = IRON_TEMP_MIN;
  if (temp_c > IRON_TEMP_MAX) temp_c = IRON_TEMP_MAX;
  g_target_c = temp_c;
}

void iron_set_heater(bool on)
{
  g_heating = on;
  if (!on)
    {
      g_integral = 0.0f;
      g_last_error = 0.0f;
      g_power = 0.0f;
      stm32_gpiowrite(IRON_GPIO_HEAT, false);
    }
}

void iron_set_pid(float p, float i, float d)
{
  g_kp = p;
  g_ki = i;
  g_kd = d;
}

void iron_get_status(FAR struct iron_status_s *st)
{
  if (st == NULL)
    {
      return;
    }

  st->temp_c    = (int)g_temp_c;
  st->target_c  = g_target_c;
  st->power_pct = g_power;
  st->heating   = g_heating;
  st->sensor_ok = g_sensor_ok;
}

