43	 * stm32_gpio.h is not on the app include path, so pinsets are built
44	 * from the documented bit layout:
45	 *   MODE bits18-19 (OUTPUT=1<<18), SPEED bits10-11 (50MHz=2<<10),
46	 *   OUTPUT_SET bit8 (0x100), PORT bits4-7 (E=4,I=8,K=10), PIN bits0-3
47	 */
48	#define GPIO_OUTPUT_VAL     (1u << 18)
49	#define GPIO_SPEED_50MHZ    (2u << 10)
50	#define GPIO_OUTPUT_SETBIT  (1u << 8)
51	
52	#define IRON_GPIO_SCK    (GPIO_OUTPUT_VAL | GPIO_SPEED_50MHZ | \
53	                          (4u << 4) | 3u)              /* D8 = PE3  */
54	#define IRON_GPIO_CS     (GPIO_OUTPUT_VAL | GPIO_SPEED_50MHZ | \
55	                          GPIO_OUTPUT_SETBIT | (8u << 4) | 8u)  /* D7 = PI8 */
