60	/* --- Timing (us) --- */
61	#define IRON_SPI_HALF_PERIOD_US  2    /* ~250kHz bit clock */
62	#define IRON_TICK_MS             100  /* PID period */
63	
64	/* --- PID limits --- */
65	#define IRON_TEMP_MIN     100
66	#define IRON_TEMP_MAX     480
67	#define IRON_PWR_MAX      100.0f
68	
69	/* PWM period in ticks (software PWM at ~1kHz => 1ms period) */
70	#define IRON_PWM_PERIOD_MS   1
71	#define IRON_PWM_TICKS       10   /* 100ms tick / 1ms period = 10 slices */
72	
73	/****************************************************************************
74	 * Private Data
75	 ****************************************************************************/
76	
77	static int   g_temp_raw    = 0;   /* last ADC code */
78	static float g_temp_c      = 25.0f;
79	static int   g_target_c    = 350;
80	static bool  g_heating     = false;
81	static bool  g_sensor_ok   = false;
82	static float g_kp          = 3.0f;
83	static float g_ki          = 0.05f;
84	static float g_kd          = 1.5f;
85	static float g_power       = 0.0f;   /* 0..100 */
86	
87	/* PID state */
88	static float g_integral    = 0.0f;
89	static float g_last_error  = 0.0f;
90	
91	/* Software PWM state: counts down every tick */
92	static int   g_pwm_slice   = 0;
