94	/****************************************************************************
95	 * Private Functions
96	 ****************************************************************************/
97	
98	/****************************************************************************
99	 * Name: iron_spi_delay
100	 ****************************************************************************/
101	
102	static inline void iron_spi_delay(void)
103	{
104	  up_udelay(IRON_SPI_HALF_PERIOD_US);
105	}
106	
107	/****************************************************************************
108	 * Name: max6675_read
109	 *
110	 * Bit-bang a 16-bit read from the MAX6675.
111	 * Returns 16-bit raw value (D2 = thermocouple open flag).
112	 ****************************************************************************/
113	
114	static uint16_t max6675_read(void)
115	{
116	  uint16_t value = 0;
117	  int i;
118	
119	  /* CS low to start */
120	  stm32_gpiowrite(IRON_GPIO_CS, false);
121	  iron_spi_delay();
122	
123	  /* Read 16 bits, MSB first, sample on rising edge */
124	  for (i = 0; i < 16; i++)
125	    {
126	      /* SCK low -> data valid to read */
127	      stm32_gpiowrite(IRON_GPIO_SCK, false);
128	      iron_spi_delay();
129	
130	      /* Sample SO on rising edge per MAX6675: data changes on falling
131	       * edge, so read while clock is low (stable). */
132	      value = (value << 1);
133	      if (stm32_gpioread(IRON_GPIO_SO))
134	        {
135	          value |= 1;
136	        }
137	
138	      /* SCK high */
139	      stm32_gpiowrite(IRON_GPIO_SCK, true);
140	      iron_spi_delay();
141	    }
142	
143	  /* CS high to end */
144	  stm32_gpiowrite(IRON_GPIO_CS, true);
145	  iron_spi_delay();
146	
147	  return value;
148	}
149	
150	/****************************************************************************
151	 * Name: max6675_temp
152	 *
153	 * Decode 16-bit read into Celsius. Returns -1000 if thermocouple open.
154	 ****************************************************************************/
155	
156	static float max6675_temp(uint16_t raw)
157	{
158	  if (raw & 0x0004)         /* D2: thermocouple open */
159	    {
160	      return -1000.0f;
161	    }
162	
163	  /* D14-D3 = 12-bit value, 0.25 C/bit */
164	  return (float)((raw >> 3) & 0x0FFF) * 0.25f;
165	}
166	
167	/****************************************************************************
168	 * Name: iron_pid_update
169	 *
170	 * Compute heater power % from PID on temperature error.
171	 ****************************************************************************/
172	
173	static void iron_pid_update(void)
174	{
175	  float error;
176	  float p_term;
177	  float i_term;
178	  float d_term;
179	  float dt_sec;
180	
181	  if (!g_heating || !g_sensor_ok)
182	    {
183	      g_power = 0.0f;
184	      g_integral = 0.0f;
185	      g_last_error = 0.0f;
186	      return;
187	    }
188	
189	  error    = (float)(g_target_c) - g_temp_c;
190	  dt_sec   = IRON_TICK_MS / 1000.0f;
191	
192	  /* Proportional */
193	  p_term = g_kp * error;
194	
195	  /* Integral with anti-windup */
196	  g_integral += error * dt_sec;
197	  if (g_integral >  1000.0f) g_integral =  1000.0f;
198	  if (g_integral < -1000.0f) g_integral = -1000.0f;
199	  i_term = g_ki * g_integral;
200	
201	  /* Derivative */
202	  d_term = g_kd * (error - g_last_error) / dt_sec;
203	
204	  g_last_error = error;
205	
206	  /* Sum and clamp 0..100 */
207	  g_power = p_term + i_term + d_term;
208	  if (g_power < 0.0f)   g_power = 0.0f;
209	  if (g_power > IRON_PWR_MAX) g_power = IRON_PWR_MAX;
210	}
211	
212	/****************************************************************************
213	 * Name: iron_pwm_apply
214	 *
215	 * Software PWM: turn heater GPIO on/off based on power %.
216	 * Called once per tick (100ms). We split the 100ms into N slices and
217	 * keep the heater on for the first (power%) slices.
218	 ****************************************************************************/
219	
220	static void iron_pwm_apply(void)
221	{
222	  int on_slices = (int)(g_power / 100.0f * IRON_PWM_TICKS);
223	
224	  if (!g_heating || on_slices <= 0)
225	    {
226	      stm32_gpiowrite(IRON_GPIO_HEAT, false);
227	      return;
228	    }
229	
230	  if (on_slices >= IRON_PWM_TICKS)
231	    {
232	      stm32_gpiowrite(IRON_GPIO_HEAT, true);
233	      return;
234	    }
235	
236	  /* Cycle through slices */
237	  g_pwm_slice++;
238	  if (g_pwm_slice >= IRON_PWM_TICKS)
239	    {
240	      g_pwm_slice = 0;
241	    }
242	
243	  stm32_gpiowrite(IRON_GPIO_HEAT, g_pwm_slice < on_slices);
244	}
