250	int iron_init(void)
251	{
252	  /* Configure GPIO pins */
253	  stm32_configgpio(IRON_GPIO_SCK);
254	  stm32_configgpio(IRON_GPIO_CS);
255	  stm32_configgpio(IRON_GPIO_SO);
256	  stm32_configgpio(IRON_GPIO_HEAT);
