258	  /* Idle states: CS high, clock low, heater off */
259	  stm32_gpiowrite(IRON_GPIO_CS, true);
260	  stm32_gpiowrite(IRON_GPIO_SCK, false);
261	  stm32_gpiowrite(IRON_GPIO_HEAT, false);
262	
263	  /* Probe MAX6675 */
264	  {
265	    uint16_t raw = max6675_read();
266	    float t = max6675_temp(raw);
267	
268	    if (t < -900.0f)
269	      {
270	        iwarn("IRON: thermocouple open (raw=0x%04x)\n", raw);
271	        g_sensor_ok = false;
272	      }
273	    else
274	      {
275	        g_temp_c = t;
276	        g_sensor_ok = true;
277	        iinfo("IRON: MAX6675 ok, T=%.1fC (raw=0x%04x)\n", t, raw);
278	      }
279	  }
280	
281	  return 0;
282	}
