void iron_tick(void)
{
  static int read_div = 0;
  uint16_t raw;
  float t;

  /* MAX6675 conversion time is 220ms; reading more often just returns
   * stale data. Read every 3rd tick (300ms) and reuse the value in
   * between for the PID loop. */
  if (++read_div >= 3)
    {
      read_div = 0;

      raw = max6675_read();
      t = max6675_temp(raw);

      if (t < -900.0f)
        {
          g_sensor_ok = false;
        }
      else
        {
          g_sensor_ok = true;
          g_temp_c = t;
        }
    }

  if (!g_sensor_ok)
    {
      /* Safety: no sensor, no heat */
      g_power = 0.0f;
      stm32_gpiowrite(IRON_GPIO_HEAT, false);
      return;
    }

  /* Run PID */
  iron_pid_update();

  /* Apply PWM */
  iron_pwm_apply();
}

