112	/****************************************************************************
113	 * Name: max6675_read
114	 *
115	 * Bit-bang a 16-bit read from the MAX6675.
116	 * Returns 16-bit raw value (D2 = thermocouple open flag).
117	 ****************************************************************************/
118	
119	static uint16_t max6675_read(void)
120	{
121	  uint16_t value = 0;
122	  int i;
123	
124	  /* CS low to start */
125	  stm32_gpiowrite(IRON_GPIO_CS, false);
126	  iron_spi_delay();
127	
128	  /* Read 16 bits, MSB first, sample on rising edge */
129	  for (i = 0; i < 16; i++)
130	    {
131	      /* SCK low -> data valid to read */
132	      stm32_gpiowrite(IRON_GPIO_SCK, false);
133	      iron_spi_delay();
134	
135	      /* Sample SO on rising edge per MAX6675: data changes on falling
136	       * edge, so read while clock is low (stable). */
137	      value = (value << 1);
138	      if (stm32_gpioread(IRON_GPIO_SO))
139	        {
140	          value |= 1;
141	        }
142	
143	      /* SCK high */
144	      stm32_gpiowrite(IRON_GPIO_SCK, true);
145	      iron_spi_delay();
146	    }
147	
148	  /* CS high to end */
149	  stm32_gpiowrite(IRON_GPIO_CS, true);
150	  iron_spi_delay();
151	
152	  return value;
153	}
