155	/****************************************************************************
156	 * Name: max6675_temp
157	 *
158	 * Decode 16-bit read into Celsius. Returns -1000 if thermocouple open.
159	 ****************************************************************************/
160	
161	static float max6675_temp(uint16_t raw)
162	{
163	  if (raw & 0x0004)         /* D2: thermocouple open */
164	    {
165	      return -1000.0f;
166	    }
167	
168	  /* D14-D3 = 12-bit value, 0.25 C/bit */
169	  return (float)((raw >> 3) & 0x0FFF) * 0.25f;
170	}
