172	/****************************************************************************
173	 * Name: iron_pid_update
174	 *
175	 * Compute heater power % from PID on temperature error.
176	 ****************************************************************************/
177	
178	static void iron_pid_update(void)
179	{
180	  float error;
181	  float p_term;
182	  float i_term;
183	  float d_term;
184	  float d_slope;
185	
186	  if (!g_heating || !g_sensor_ok)
187	    {
188	      g_power = 0.0f;
189	      g_integral = 0.0f;
190	      g_last_error = 0.0f;
191	      return;
192	    }
193	
194	  error = (float)(g_target_c) - g_temp_c;
195	
196	  /* Proportional */
197	  p_term = g_kp * error;
198	
199	  /* Integral with anti-windup */
200	  g_integral += error * (IRON_TICK_MS / 1000.0f);
201	  if (g_integral >  1000.0f) g_integral =  1000.0f;
202	  if (g_integral < -1000.0f) g_integral = -1000.0f;
203	  i_term = g_ki * g_integral;
204	
205	  /* Derivative on error change, slope-limited so a single quantized
206	   * temperature step cannot spike the output (100ms sampling noise). */
207	  d_slope = (error - g_last_error) / (IRON_TICK_MS / 1000.0f);
208	  if (d_slope >  IRON_D_MAX_SLOPE) d_slope =  IRON_D_MAX_SLOPE;
209	  if (d_slope < -IRON_D_MAX_SLOPE) d_slope = -IRON_D_MAX_SLOPE;
210	  d_term = g_kd * d_slope;
211	
212	  g_last_error = error;
213	
214	  /* Sum and clamp 0..100 */
215	  g_power = p_term + i_term + d_term;
216	  if (g_power < 0.0f)   g_power = 0.0f;
217	  if (g_power > IRON_PWR_MAX) g_power = IRON_PWR_MAX;
218	}
