220	/****************************************************************************
221	 * Name: iron_pwm_apply
222	 *
223	 * Software PWM: turn heater GPIO on/off based on power %.
224	 * Called once per tick (100ms). We split the 100ms into N slices and
225	 * keep the heater on for the first (power%) slices.
226	 ****************************************************************************/
227	
228	static void iron_pwm_apply(void)
229	{
230	  int on_slices = (int)(g_power / 100.0f * IRON_PWM_TICKS);
231	
232	  if (!g_heating || on_slices <= 0)
233	    {
234	      stm32_gpiowrite(IRON_GPIO_HEAT, false);
235	      return;
236	    }
237	
238	  if (on_slices >= IRON_PWM_TICKS)
239	    {
240	      stm32_gpiowrite(IRON_GPIO_HEAT, true);
241	      return;
242	    }
243	
244	  /* Cycle through slices */
245	  g_pwm_slice++;
246	  if (g_pwm_slice >= IRON_PWM_TICKS)
247	    {
248	      g_pwm_slice = 0;
249	    }
250	
251	  stm32_gpiowrite(IRON_GPIO_HEAT, g_pwm_slice < on_slices);
252	}
