257	
258	int iron_init(void)
259	{
260	  /* Configure GPIO pins */
261	  stm32_configgpio(IRON_GPIO_SCK);
262	  stm32_configgpio(IRON_GPIO_CS);
263	  stm32_configgpio(IRON_GPIO_SO);
264	  stm32_configgpio(IRON_GPIO_HEAT);
265	
266	  /* Idle states: CS high, clock low, heater off */
267	  stm32_gpiowrite(IRON_GPIO_CS, true);
268	  stm32_gpiowrite(IRON_GPIO_SCK, false);
269	  stm32_gpiowrite(IRON_GPIO_HEAT, false);
270	
271	  /* Probe MAX6675 */
272	  {
273	    uint16_t raw = max6675_read();
274	    float t = max6675_temp(raw);
275	
276	    if (t < -900.0f)
277	      {
278	        iwarn("IRON: thermocouple open (raw=0x%04x)\n", raw);
279	        g_sensor_ok = false;
280	      }
281	    else
282	      {
283	        g_temp_c = t;
284	        g_sensor_ok = true;
285	        iinfo("IRON: MAX6675 ok, T=%.1fC (raw=0x%04x)\n", t, raw);
286	      }
287	  }
288	
289	  return 0;
290	}
291	
292	void iron_tick(void)
293	{
294	  static int read_div = 0;
295	  uint16_t raw;
296	  float t;
297	
298	  /* MAX6675 conversion time is 220ms; reading more often just returns
299	   * stale data. Read every 3rd tick (300ms) and reuse the value in
300	   * between for the PID loop. */
301	  if (++read_div >= 3)
302	    {
303	      read_div = 0;
304	
305	      raw = max6675_read();
306	      t = max6675_temp(raw);
307	
308	      if (t < -900.0f)
309	        {
310	          g_sensor_ok = false;
311	        }
312	      else
313	        {
314	          g_sensor_ok = true;
315	          g_temp_c = t;
316	        }
317	    }
318	
319	  if (!g_sensor_ok)
320	    {
321	      /* Safety: no sensor, no heat */
322	      g_power = 0.0f;
323	      stm32_gpiowrite(IRON_GPIO_HEAT, false);
324	      return;
325	    }
326	
327	  /* Run PID */
328	  iron_pid_update();
329	
330	  /* Apply PWM */
331	  iron_pwm_apply();
332	}
333	
334	void iron_set_target(int temp_c)
335	{
336	  if (temp_c < IRON_TEMP_MIN) temp_c = IRON_TEMP_MIN;
337	  if (temp_c > IRON_TEMP_MAX) temp_c = IRON_TEMP_MAX;
338	  g_target_c = temp_c;
339	}
340	
341	void iron_set_heater(bool on)
342	{
343	  g_heating = on;
344	  if (!on)
345	    {
346	      g_integral = 0.0f;
347	      g_last_error = 0.0f;
348	      g_power = 0.0f;
349	      stm32_gpiowrite(IRON_GPIO_HEAT, false);
350	    }
351	}
352	
353	void iron_set_pid(float p, float i, float d)
354	{
355	  g_kp = p;
356	  g_ki = i;
357	  g_kd = d;
358	}
359	
360	void iron_get_status(FAR struct iron_status_s *st)
361	{
362	  if (st == NULL)
363	    {
364	      return;
365	    }
366	
367	  st->temp_c    = (int)g_temp_c;
368	  st->target_c  = g_target_c;
369	  st->power_pct = g_power;
370	  st->heating   = g_heating;
371	  st->sensor_ok = g_sensor_ok;
372	}
