/****************************************************************************
 * Name: ui_ai_drag_cb
 *
 * Drag the floating AI icon while pressed. Updates its absolute pos,
 * clamped to screen bounds.
 ****************************************************************************/

static void ui_ai_drag_cb(lv_event_t *e)
{
  lv_obj_t *btn = lv_event_get_target(e);
  lv_indev_t *indev = lv_indev_get_active();
  lv_point_t p;

  if (indev == NULL)
    {
      return;
    }

  lv_indev_get_point(indev, &p);
  lv_obj_set_pos(btn,
                 p.x - AI_BTN_SIZE / 2,
                 p.y - AI_BTN_SIZE / 2);

  /* Clamp to screen */
  if (lv_obj_get_x(btn) < 0)
    {
      lv_obj_set_x(btn, 0);
    }
  else if (lv_obj_get_x(btn) > SCREEN_W - AI_BTN_SIZE)
    {
      lv_obj_set_x(btn, SCREEN_W - AI_BTN_SIZE);
    }

  if (lv_obj_get_y(btn) < 0)
    {
      lv_obj_set_y(btn, 0);
    }
  else if (lv_obj_get_y(btn) > SCREEN_H - AI_BTN_SIZE)
    {
      lv_obj_set_y(btn, SCREEN_H - AI_BTN_SIZE);
    }
}

