/****************************************************************************
 * Name: ui_ai_press_cb / ui_ai_release_cb
 *
 * Remember press position; suppress toggle if the icon was dragged.
 ****************************************************************************/

static void ui_ai_press_cb(lv_event_t *e)
{
  lv_indev_t *indev = lv_event_get_indev(e);
  lv_point_t p;

  g_ai_dragged = false;
  if (indev != NULL)
    {
      lv_indev_get_point(indev, &p);
      g_ai_press_x = p.x;
      g_ai_press_y = p.y;
    }
}

static void ui_ai_release_cb(lv_event_t *e)
{
  /* If dragged, this was NOT a tap: cancel the pending click */
  if (g_ai_dragged)
    {
      lv_obj_t *btn = lv_event_get_target(e);
      lv_event_code_t code = lv_event_get_code(e);
      if (code == LV_EVENT_RELEASED)
        {
          lv_indev_t *indev = lv_event_get_indev(e);
          if (indev != NULL)
            {
              lv_indev_reset(indev, btn);
            }
        }
    }
}

