static void ui_ai_toggle_cb(lv_event_t *e)
{
  /* After a drag, ignore this click (it was a move, not a tap) */
  if (g_ai_dragged)
    {
      g_ai_dragged = false;
      return;
    }

  if (g_ai_state == AI_STATE_CLOSED)
    {
      lv_obj_remove_flag(g_ai_panel, LV_OBJ_FLAG_HIDDEN);
      g_ai_state = AI_STATE_OPEN;
