43	/* --- GPIO pin assignments (Arduino D4/D6/D7/D8) ---
44	 * stm32_gpio.h is not on the app include path, so pinsets are built
45	 * from the documented bit layout:
46	 *   MODE bits18-19 (OUTPUT=1<<18), SPEED bits10-11 (50MHz=2<<10),
47	 *   OUTPUT_SET bit8 (0x100), PORT bits4-7 (E=4,I=8,K=10), PIN bits0-3
48	 */
49	#define GPIO_OUTPUT_VAL     (1u << 18)
50	#define GPIO_SPEED_50MHZ    (2u << 10)
51	#define GPIO_OUTPUT_SETBIT  (1u << 8)
52	#define GPIO_PULLUP         (1u << 16)
