54	#define IRON_GPIO_SCK    (GPIO_OUTPUT_VAL | GPIO_SPEED_50MHZ | \
55	                          (4u << 4) | 3u)              /* D8 = PE3  */
56	#define IRON_GPIO_CS     (GPIO_OUTPUT_VAL | GPIO_SPEED_50MHZ | \
57	                          GPIO_OUTPUT_SETBIT | (8u << 4) | 8u)  /* D7 = PI8 */
58	#define IRON_GPIO_SO     ((4u << 4) | 6u)               /* D6 = PE6 input */
59	#define IRON_GPIO_HEAT   (GPIO_OUTPUT_VAL | GPIO_SPEED_50MHZ | \
60	                          (10u << 4) | 1u)             /* D4 = PK1  */
61	#define IRON_GPIO_SLEEP  (GPIO_PULLUP | (6u << 4) | 3u) /* D2 = PG3, active low */
62	
63	/* --- Timing (us) --- */
64	#define IRON_SPI_HALF_PERIOD_US  2    /* ~250kHz bit clock */
65	#define IRON_TICK_MS             100  /* PID period */
66	
67	/* --- PID limits --- */
68	#define IRON_TEMP_MIN     100
69	#define IRON_TEMP_MAX     480
70	#define IRON_TEMP_CUTOFF  500
71	#define IRON_PWR_MAX      100.0f
72	#define IRON_PID_DT       (IRON_TICK_MS / 1000.0f)
73	#define IRON_PID_KP_MAX   20.0f
