78	/* Software PWM: the iron module ticks every 100ms; the PWM cycle spans
79	 * IRON_PWM_TICKS ticks => 1s period (1Hz). Soldering irons have large
80	 * thermal inertia, so 1Hz duty control is fine. power% => the heater
81	 * stays ON for the first N slices of each cycle, OFF for the rest. */
82	#define IRON_PWM_TICKS       10   /* 1s cycle = 10 x 100ms slices */
83	
84	/* Derivative low-pass: limit D-term response per tick to avoid
85	 * oscillation from quantized (100ms-sampled) temperature. */
86	#define IRON_D_MAX_SLOPE     8.0f   /* max % output change from D per tick */
