100	static bool  g_sensor_ok   = false;
101	static float g_kp          = 3.0f;
102	static float g_ki          = 0.05f;
103	static float g_kd          = 1.5f;
104	static float g_power       = 0.0f;   /* 0..100 */
105	
106	/* PID state */
107	static float g_integral    = 0.0f;
108	static float g_last_temp_c = 25.0f;
109	static bool  g_have_sample = false;
110	static float g_sample_age  = 0.0f;
111	
112	/* Software PWM state: counts down every tick */
113	static int   g_pwm_slice   = 0;
114	
115	/* JBC245 sleep state */
116	static bool  g_sleep_pin_deb   = false;
117	static int   g_sleep_deb_cnt   = 0;
118	static int   g_sleep_ticks     = 0;
119	static int   g_sleep_stage     = IRON_SLEEP_ACTIVE;
120	static int   g_standby_c       = IRON_STANDBY_DEFAULT_C;
121	static int   g_target_eff_c    = 350;
