127	/****************************************************************************
128	 * Name: iron_spi_delay
129	 ****************************************************************************/
130	
131	static inline void iron_spi_delay(void)
132	{
133	  up_udelay(IRON_SPI_HALF_PERIOD_US);
134	}
135	
136	/****************************************************************************
137	 * Name: max6675_read
138	 *
139	 * Bit-bang a 16-bit read from the MAX6675.
140	 * Returns 16-bit raw value (D2 = thermocouple open flag).
141	 ****************************************************************************/
142	
143	static uint16_t max6675_read(void)
144	{
145	  uint16_t value = 0;
146	  int i;
147	
148	  /* CS low to start */
149	  stm32_gpiowrite(IRON_GPIO_CS, false);
150	  iron_spi_delay();
151	
152	  /* Read 16 bits MSB first.  The MAX6675 updates SO after the falling
153	   * edge; sample each bit while SCK is low and stable. */
154	  for (i = 0; i < 16; i++)
155	    {
156	      /* SCK low -> data valid to read */
157	      stm32_gpiowrite(IRON_GPIO_SCK, false);
158	      iron_spi_delay();
159	
160	      /* Sample SO on rising edge per MAX6675: data changes on falling
161	       * edge, so read while clock is low (stable). */
162	      value = (value << 1);
163	      if (stm32_gpioread(IRON_GPIO_SO))
164	        {
165	          value |= 1;
166	        }
167	
168	      /* SCK high */
169	      stm32_gpiowrite(IRON_GPIO_SCK, true);
170	      iron_spi_delay();
171	    }
172	
173	  /* CS high to end */
174	  stm32_gpiowrite(IRON_GPIO_CS, true);
175	  iron_spi_delay();
176	
177	  return value;
178	}
179	
180	/****************************************************************************
181	 * Name: max6675_temp
182	 *
183	 * Decode 16-bit read into Celsius. Returns -1000 if thermocouple open.
184	 ****************************************************************************/
185	
186	static bool max6675_temp(uint16_t raw, FAR float *temp_c)
187	{
188	  uint16_t code;
189	
190	  if (temp_c == NULL || (raw & 0x8000) != 0 || (raw & 0x0002) != 0 ||
191	      (raw & 0x0004) != 0)
192	    {
193	      return false;
194	    }
195	
196	  code = (raw >> 3) & 0x0fff;
197	  *temp_c = (float)code * 0.25f;
198	  return *temp_c >= 0.0f && *temp_c <= 1023.75f;
199	}
