201	/****************************************************************************
202	 * Name: iron_pid_update
203	 *
204	 * Compute heater power % from PID on temperature error.
205	 ****************************************************************************/
206	
207	static void iron_pid_update(float dt)
208	{
209	  float error;
210	  float p_term;
211	  float i_term;
212	  float d_term;
213	  float d_slope;
214	  float candidate;
215	
216	  if (!g_heating || !g_sensor_ok || !g_have_sample)
217	    {
218	      g_power = 0.0f;
219	      g_integral = 0.0f;
220	      return;
221	    }
222	
223	  error = (float)g_target_eff_c - g_temp_c;
224	  p_term = g_kp * error;
225	  d_slope = (g_temp_c - g_last_temp_c) / dt;
226	  if (d_slope > IRON_D_MAX_SLOPE) d_slope = IRON_D_MAX_SLOPE;
227	  if (d_slope < -IRON_D_MAX_SLOPE) d_slope = -IRON_D_MAX_SLOPE;
228	  d_term = -g_kd * d_slope;
229	
230	  /* Conditional integration: do not integrate farther into saturation. */
231	  candidate = p_term + g_ki * g_integral + d_term;
232	  if (!((candidate >= IRON_PWR_MAX && error > 0.0f) ||
233	        (candidate <= 0.0f && error < 0.0f)))
234	    {
235	      g_integral += error * dt;
236	      if (g_integral > 1000.0f) g_integral = 1000.0f;
237	      if (g_integral < -1000.0f) g_integral = -1000.0f;
238	    }
239	
240	  i_term = g_ki * g_integral;
241	  g_power = p_term + i_term + d_term;
242	  if (g_power < 0.0f) g_power = 0.0f;
243	  if (g_power > IRON_PWR_MAX) g_power = IRON_PWR_MAX;
244	}
245	
246	/****************************************************************************
247	 * Name: iron_pwm_apply
248	 *
249	 * Software PWM: turn heater GPIO on/off based on power %.
250	 * Called once per tick (100ms). We split the 100ms into N slices and
251	 * keep the heater on for the first (power%) slices.
252	 ****************************************************************************/
253	
254	static void iron_pwm_apply(void)
255	{
256	  int on_slices = (int)(g_power / 100.0f * IRON_PWM_TICKS);
257	
258	  if (!g_heating || on_slices <= 0)
259	    {
260	      g_pwm_slice = 0;
261	      stm32_gpiowrite(IRON_GPIO_HEAT, false);
262	      return;
263	    }
264	
265	  if (on_slices >= IRON_PWM_TICKS)
266	    {
267	      stm32_gpiowrite(IRON_GPIO_HEAT, true);
268	      return;
269	    }
270	
271	  stm32_gpiowrite(IRON_GPIO_HEAT, g_pwm_slice < on_slices);
272	  g_pwm_slice++;
273	  if (g_pwm_slice >= IRON_PWM_TICKS)
274	    {
275	      g_pwm_slice = 0;
276	    }
277	}
278	
279	/****************************************************************************
280	 * Name: iron_sleep_tick
281	 *
282	 * Debounce the JBC245 SLEEP pin and drive the sleep stage:
283	 *   ACTIVE -> HOLD (in stand) -> STANDBY_TEMP after IRON_SLEEP_ENTER_TICKS.
284	 *   Leave stand at any time: back to ACTIVE and restore the user target.
285	 ****************************************************************************/
286	
287	static void iron_sleep_tick(void)
288	{
289	  bool raw;
290	  bool sleep_now;
291	
292	  raw = !stm32_gpioread(IRON_GPIO_SLEEP);   /* active low: in stand */
293	
294	  /* Bounce filter: require N consecutive identical samples. */
295	  if (raw != g_sleep_pin_deb)
296	    {
297	      g_sleep_deb_cnt++;
298	      if (g_sleep_deb_cnt >= IRON_SLEEP_DEBOUNCE_TICKS)
299	        {
300	          g_sleep_pin_deb = raw;
301	          g_sleep_deb_cnt = 0;
302	        }
303	    }
304	  else
305	    {
306	      g_sleep_deb_cnt = 0;
307	    }
308	
309	  sleep_now = g_sleep_pin_deb;
310	
311	  if (!sleep_now && g_sleep_stage != IRON_SLEEP_ACTIVE)
312	    {
313	      /* Picked up: restore user target and PID history. */
314	      g_sleep_stage = IRON_SLEEP_ACTIVE;
315	      g_sleep_ticks = 0;
316	      g_integral = 0.0f;
317	      g_last_temp_c = g_temp_c;
318	      g_target_eff_c = g_target_c;
319	    }
320	  else if (sleep_now && g_sleep_stage == IRON_SLEEP_ACTIVE)
321	    {
322	      g_sleep_stage = IRON_SLEEP_HOLD;
323	      g_sleep_ticks = 0;
324	    }
325	  else if (g_sleep_stage == IRON_SLEEP_HOLD)
326	    {
327	      g_sleep_ticks++;
328	      if (g_sleep_ticks >= IRON_SLEEP_ENTER_TICKS)
329	        {
330	          g_sleep_stage = IRON_SLEEP_STANDBY_TEMP;
331	          g_integral = 0.0f;
332	          g_target_eff_c = g_standby_c;
333	        }
334	    }
335	}
