338	int iron_init(void)
339	{
340	  /* Configure GPIO pins */
341	  stm32_configgpio(IRON_GPIO_SCK);
342	  stm32_configgpio(IRON_GPIO_CS);
343	  stm32_configgpio(IRON_GPIO_SO);
344	  stm32_configgpio(IRON_GPIO_HEAT);
345	  stm32_configgpio(IRON_GPIO_SLEEP);
346	
347	  /* Idle states: CS high, clock low, heater off */
348	  stm32_gpiowrite(IRON_GPIO_CS, true);
349	  stm32_gpiowrite(IRON_GPIO_SCK, false);
350	  stm32_gpiowrite(IRON_GPIO_HEAT, false);
351	
352	  /* Probe MAX6675 */
353	  {
354	    uint16_t raw = max6675_read();
355	    float t;
356	
357	    if (!max6675_temp(raw, &t))
358	      {
359	        iwarn("IRON: invalid MAX6675 frame (raw=0x%04x)\n", raw);
360	        g_sensor_ok = false;
361	      }
362	    else
363	      {
364	        g_temp_c = t;
365	        g_last_temp_c = t;
366	        g_have_sample = true;
367	        g_sample_age = 0.0f;
368	        g_sensor_ok = true;
369	        iinfo("IRON: MAX6675 ok, T=%.1fC (raw=0x%04x)\n", t, raw);
370	      }
371	  }
372	
373	  return 0;
374	}
375	
376	void iron_tick(void)
377	{
378	  static int read_div = 0;
379	  uint16_t raw;
380	  float t;
381	  bool fresh_sample = false;
382	
383	  g_sample_age += IRON_PID_DT;
384	
385	  /* JBC245 sleep detection runs every tick, before sampling. */
386	  iron_sleep_tick();
387	
388	  /* CS high starts a conversion.  Read only after three 100ms ticks so the
389	   * MAX6675 has exceeded its 220ms maximum conversion time. */
390	  if (++read_div >= 3)
391	    {
392	      read_div = 0;
393	      raw = max6675_read();
394	
395	      if (max6675_temp(raw, &t))
396	        {
397	          if (t >= IRON_TEMP_CUTOFF)
398	            {
399	              iwarn("IRON: over-temperature %.1fC\n", t);
400	              g_sensor_ok = false;
401	            }
402	          else
403	            {
404	              g_last_temp_c = g_temp_c;
405	              g_temp_c = t;
406	              g_sample_age = 0.0f;
407	              g_have_sample = true;
408	              g_sensor_ok = true;
409	              fresh_sample = true;
410	            }
411	        }
412	      else
413	        {
414	          iwarn("IRON: invalid MAX6675 frame (raw=0x%04x)\n", raw);
415	          g_sensor_ok = false;
416	        }
417	    }
418	
419	  if (!g_sensor_ok || g_sample_age > IRON_SAMPLE_MAX_AGE)
420	    {
421	      /* A stale or invalid sensor reading must always shut the heater off. */
422	      g_sensor_ok = false;
423	      g_power = 0.0f;
424	      g_integral = 0.0f;
425	      g_pwm_slice = 0;
426	      stm32_gpiowrite(IRON_GPIO_HEAT, false);
427	      return;
428	    }
429	
430	  if (fresh_sample)
431	    {
432	      iron_pid_update(IRON_PID_DT * 3.0f);
433	    }
434	
435	  iron_pwm_apply();
436	}
437	
438	void iron_set_target(int temp_c)
439	{
440	  if (temp_c < IRON_TEMP_MIN) temp_c = IRON_TEMP_MIN;
441	  if (temp_c > IRON_TEMP_MAX) temp_c = IRON_TEMP_MAX;
442	  if (temp_c != g_target_c)
443	    {
444	      g_integral = 0.0f;
445	      g_last_temp_c = g_temp_c;
446	    }
447	
448	  g_target_c = temp_c;
449	  if (g_sleep_stage == IRON_SLEEP_ACTIVE)
450	    {
451	      g_target_eff_c = temp_c;
452	    }
453	}
