473	void iron_set_pid(float p, float i, float d)
474	{
475	  if (!isfinite(p) || !isfinite(i) || !isfinite(d) || p < 0.0f ||
476	      i < 0.0f || d < 0.0f || p > IRON_PID_KP_MAX ||
477	      i > IRON_PID_KI_MAX || d > IRON_PID_KD_MAX)
