1	/****************************************************************************
2	 * Contest 2026 team 008 - SW3538 fast-charge chip driver (NuttX)
3	 *
4	 * Four SW3538 devices share I2C address 0x3c behind a TCA9548A at 0x70.
5	 * Each transaction selects exactly one TCA downstream channel first.
6	 ****************************************************************************/
7	
8	#include <nuttx/config.h>
9	
10	#include <stdint.h>
11	#include <string.h>
12	#include <errno.h>
13	#include <debug.h>
14	
15	#include <nuttx/i2c/i2c_master.h>
16	#include <nuttx/arch.h>
17	#include <arch/board/board.h>
18	
19	#include "sw3538.h"
20	
21	extern FAR struct i2c_master_s *stm32_i2cbus_initialize(int bus);
22	
23	/****************************************************************************
24	 * Pre-processor Definitions
25	 ****************************************************************************/
26	
27	#define SW3538_ADDR              0x3c
28	#define TCA9548A_ADDR            0x70
29	#define SW3538_FREQ              100000
30	#define SW3538_CHANNEL_COUNT     4
31	
32	#define SW3538_REG_PROTO         0x09
33	#define SW3538_REG_ONLINE        0x0d
34	#define SW3538_REG_ADC_SEL       0x40
35	#define SW3538_REG_ADC_LO        0x41
36	#define SW3538_REG_ADC_HI        0x42
37	#define SW3538_REG_NTC_CURRENT   0x44
38	
39	#define ADC_CH_IC                1
40	#define ADC_CH_IA                2
41	#define ADC_CH_VOUT              5
42	#define ADC_CH_NTC               7
43	
44	#define NTC_UV_PER_BIT           1200u
45	#define NTC_CURRENT_LOW_UA       20u
46	#define NTC_CURRENT_HIGH_UA      40u
47	
48	/****************************************************************************
49	 * Private Data
50	 ****************************************************************************/
51	
52	static FAR struct i2c_master_s *g_i2c;
53	
54	/* 104AT 100K NTC nominal resistance table.  The values must be calibrated
55	 * against the actual module at room temperature before they are relied upon
56	 * for thermal decisions.  This driver reports invalid data rather than a
57	 * fabricated temperature for values outside the supported table. */
58	
59	struct ntc_point_s
60	{
61	  int16_t temp_c;
62	  uint32_t resistance_ohm;
63	};
64	
65	static const struct ntc_point_s g_ntc_104at[] =
66	{
67	  {  0, 355000 }, { 10, 202000 }, { 20, 125000 }, { 25, 100000 },
68	  { 30,  80500 }, { 40,  51000 }, { 50,  33500 }, { 60,  22400 },
69	  { 70,  15300 }, { 80,  10600 }, { 90,   7400 }, {100,   5250 },
70	  {110,   3800 }, {120,   2800 },
71	};
72	
73	/****************************************************************************
74	 * Private Functions
75	 ****************************************************************************/
76	
77	static int tca9548a_write(uint8_t value)
78	{
79	  struct i2c_msg_s msg;
80	
81	  if (g_i2c == NULL)
82	    {
83	      return -ENODEV;
84	    }
85	
86	  msg.frequency = SW3538_FREQ;
87	  msg.addr = TCA9548A_ADDR;
88	  msg.flags = 0;
89	  msg.buffer = &value;
90	  msg.length = 1;
91	  return I2C_TRANSFER(g_i2c, &msg, 1);
92	}
93	
94	static int tca9548a_select(uint8_t channel)
95	{
96	  if (channel >= SW3538_CHANNEL_COUNT)
97	    {
98	      return -EINVAL;
99	    }
100	
101	  return tca9548a_write((uint8_t)(1u << channel));
102	}
103	
104	static int sw3538_read_regs(uint8_t reg, uint8_t *buf, int len)
105	{
106	  struct i2c_msg_s msg[2];
107	  uint8_t regaddr = reg;
108	
109	  if (g_i2c == NULL)
110	    {
111	      return -ENODEV;
112	    }
113	
114	  msg[0].frequency = SW3538_FREQ;
115	  msg[0].addr = SW3538_ADDR;
116	  msg[0].flags = 0;
117	  msg[0].buffer = &regaddr;
118	  msg[0].length = 1;
119	
120	  msg[1].frequency = SW3538_FREQ;
121	  msg[1].addr = SW3538_ADDR;
122	  msg[1].flags = I2C_M_READ;
123	  msg[1].buffer = buf;
124	  msg[1].length = len;
125	
126	  return I2C_TRANSFER(g_i2c, msg, 2);
127	}
128	
129	static int sw3538_write_reg(uint8_t reg, uint8_t val)
130	{
131	  struct i2c_msg_s msg;
132	  uint8_t tx[2] = { reg, val };
133	
134	  if (g_i2c == NULL)
135	    {
136	      return -ENODEV;
137	    }
138	
139	  msg.frequency = SW3538_FREQ;
140	  msg.addr = SW3538_ADDR;
141	  msg.flags = 0;
142	  msg.buffer = tx;
143	  msg.length = sizeof(tx);
144	  return I2C_TRANSFER(g_i2c, &msg, 1);
145	}
146	
147	static int sw3538_adc_code(uint8_t channel, FAR uint16_t *code)
148	{
149	  uint8_t lo;
150	  uint8_t hi;
151	  int ret;
152	
153	  if (code == NULL)
154	    {
155	      return -EINVAL;
156	    }
157	
158	  ret = sw3538_write_reg(SW3538_REG_ADC_SEL, channel);
159	  if (ret < 0)
160	    {
161	      return ret;
162	    }
163	
164	  up_udelay(5000);
165	
166	  ret = sw3538_read_regs(SW3538_REG_ADC_LO, &lo, 1);
167	  if (ret < 0)
168	    {
169	      return ret;
170	    }
171	
172	  ret = sw3538_read_regs(SW3538_REG_ADC_HI, &hi, 1);
173	  if (ret < 0)
174	    {
175	      return ret;
176	    }
177	
178	  *code = (uint16_t)(((uint16_t)(hi & 0x0f) << 8) | lo);
179	  return OK;
180	}
181	
182	static bool sw3538_ntc_to_temp(uint16_t code, uint8_t ntc_current,
183	                               FAR int16_t *temp_c)
184	{
185	  uint32_t current_ua;
186	  uint32_t resistance;
187	  unsigned int i;
188	
189	  if (code == 0 || temp_c == NULL)
190	    {
191	      return false;
192	    }
193	
194	  current_ua = (ntc_current & 0x80) ? NTC_CURRENT_HIGH_UA :
195	                                      NTC_CURRENT_LOW_UA;
196	  resistance = ((uint32_t)code * NTC_UV_PER_BIT) / current_ua;
197	
198	  if (resistance > g_ntc_104at[0].resistance_ohm ||
199	      resistance < g_ntc_104at[(sizeof(g_ntc_104at) /
200	                                 sizeof(g_ntc_104at[0])) - 1].resistance_ohm)
201	    {
202	      return false;
203	    }
204	
205	  for (i = 0; i < (sizeof(g_ntc_104at) / sizeof(g_ntc_104at[0])) - 1; i++)
206	    {
207	      const struct ntc_point_s *high = &g_ntc_104at[i];
208	      const struct ntc_point_s *low = &g_ntc_104at[i + 1];
209	
210	      if (resistance <= high->resistance_ohm &&
211	          resistance >= low->resistance_ohm)
212	        {
213	          uint32_t span = high->resistance_ohm - low->resistance_ohm;
214	          uint32_t offset = high->resistance_ohm - resistance;
215	
216	          *temp_c = (int16_t)(high->temp_c +
217	                    ((int32_t)offset * (low->temp_c - high->temp_c) / span));
218	          return true;
219	        }
220	    }
221	
222	  return false;
223	}
224	
225	/****************************************************************************
226	 * Public Functions
227	 ****************************************************************************/
228	
229	int sw3538_init(int bus)
230	{
231	  int ret;
232	
233	  if (bus < 0)
234	    {
235	      return -EINVAL;
236	    }
237	
238	  g_i2c = stm32_i2cbus_initialize(bus);
239	  if (g_i2c == NULL)
240	    {
241	      ierr("SW3538: failed to initialize I2C%d\n", bus);
242	      return -ENODEV;
243	    }
244	
245	  ret = tca9548a_write(0);
246	  if (ret < 0)
247	    {
248	      ierr("SW3538: no TCA9548A ACK at 0x%02x\n", TCA9548A_ADDR);
249	      return ret;
250	    }
251	
252	  iinfo("SW3538: TCA9548A ready at 0x%02x on I2C%d\n",
253	        TCA9548A_ADDR, bus);
254	  return OK;
255	}
256	
257	int sw3538_read_status_channel(uint8_t channel,
258	                                FAR struct sw3538_status_s *st)
259	{
260	  uint16_t code;
261	  uint8_t proto;
262	  uint8_t online;
263	  uint8_t ntc_current;
264	  int ret;
265	
266	  if (st == NULL)
267	    {
268	      return -EINVAL;
269	    }
270	
271	  memset(st, 0, sizeof(*st));
272	
273	  ret = tca9548a_select(channel);
274	  if (ret < 0)
275	    {
276	      return ret;
277	    }
278	
279	  ret = sw3538_read_regs(SW3538_REG_PROTO, &proto, 1);
280	  if (ret < 0)
281	    {
282	      return ret;
283	    }
284	
285	  ret = sw3538_read_regs(SW3538_REG_ONLINE, &online, 1);
286	  if (ret < 0)
287	    {
288	      return ret;
289	    }
290	
291	  ret = sw3538_adc_code(ADC_CH_VOUT, &code);
292	  if (ret < 0)
293	    {
294	      return ret;
295	    }
296	  st->vout_mv = (uint16_t)(code * 6u);
297	
298	  ret = sw3538_adc_code(ADC_CH_IC, &code);
299	  if (ret < 0)
300	    {
301	      return ret;
302	    }
303	  st->ic_ma = (uint16_t)(code * 25u / 10u);
304	
305	  ret = sw3538_adc_code(ADC_CH_IA, &code);
306	  if (ret < 0)
307	    {
308	      return ret;
309	    }
310	  st->ia_ma = (uint16_t)(code * 25u / 10u);
311	
312	  ret = sw3538_read_regs(SW3538_REG_NTC_CURRENT, &ntc_current, 1);
313	  if (ret < 0)
314	    {
315	      return ret;
316	    }
317	
318	  ret = sw3538_adc_code(ADC_CH_NTC, &code);
319	  if (ret < 0)
320	    {
321	      return ret;
322	    }
323	
324	  st->temp_valid = sw3538_ntc_to_temp(code, ntc_current, &st->temp_c);
325	  st->proto = proto & 0x0f;
326	  st->online = online & 0x03;
327	  return OK;
328	}
329	
330	int sw3538_read_status(FAR struct sw3538_status_s *st)
331	{
332	  return sw3538_read_status_channel(0, st);
333	}
334	
335	const char *sw3538_proto_name(uint8_t proto)
336	{
337	  switch (proto)
338	    {
339	      case 0:  return "IDLE";
340	      case 1:  return "QC2.0";
341	      case 2:  return "QC3.0";
342	      case 3:  return "QC3+";
343	      case 4:  return "FCP";
344	      case 5:  return "SCP";
345	      case 6:  return "PD";
346	      case 7:  return "PD-PPS";
347	      case 8:  return "PE1.1";
348	      case 9:  return "PE2.0";
349	      case 10: return "VOOC1";
350	      case 11: return "VOOC4";
351	      case 13: return "SFCP";
352	      case 14: return "AFC";
353	      case 15: return "TFCP";
354	      default: return "?";
355	    }
356	}
