14	#include <syslog.h>
15	#include <unistd.h>
16	
17	#include <lvgl/lvgl.h>
18	
19	#include "charging_station_ui.h"
20	#include "sw3538.h"
21	#include "iron.h"
22	
23	/****************************************************************************
24	 * Pre-processor Definitions
25	 ****************************************************************************/
26	
27	#define SW3538_I2C_BUS      4    /* I2C4 (D14=SDA/PD13, D15=SCL/PD12) */
28	
29	/****************************************************************************
30	 * Private Data
31	 ****************************************************************************/
32	
33	static bool g_sw3538_ok[4];
34	
35	/****************************************************************************
36	 * Private Functions
37	 ****************************************************************************/
38	
39	/****************************************************************************
40	 * Name: sw3538_poll
41	 *
42	 * Read SW3538 and push real data into UI channel 1.
43	 * On failure, mark channel idle but keep the app running.
44	 ****************************************************************************/
45	
46	static void sw3538_poll(void)
47	{
48	  int channel;
49	
50	  for (channel = 0; channel < 4; channel++)
51	    {
52	      struct sw3538_status_s st;
53	      int ret;
54	
55	      if (!g_sw3538_ok[channel])
56	        {
57	          continue;
58	        }
59	
60	      ret = sw3538_read_status_channel(channel, &st);
61	      if (ret < 0)
62	        {
63	          syslog(LOG_WARNING, "SW3538 CH%d read failed: %d\n", channel + 1,
64	                 ret);
65	          cs_ui_set_channel_online(channel, false, false);
66	          continue;
67	        }
68	
69	      cs_ui_set_channel_ports(channel, (float)st.vout_mv / 1000.0f,
70	                              (float)st.ic_ma / 1000.0f,
71	                              (float)st.vout_mv / 1000.0f,
72	                              (float)st.ia_ma / 1000.0f,
73	                              sw3538_proto_name(st.proto), st.temp_c,
74	                              st.temp_valid);
75	      cs_ui_set_channel_online(channel, (st.online & 0x02) != 0,
76	                               (st.online & 0x01) != 0);
77	
78	      syslog(LOG_INFO, "SW3538 CH%d: Vout=%dmV Ic=%dmA Ia=%dmA "
79	             "temp=%s%dC proto=%d(%s)\n", channel + 1, st.vout_mv,
80	             st.ic_ma, st.ia_ma, st.temp_valid ? "" : "N/A ", st.temp_c,
81	             st.proto, sw3538_proto_name(st.proto));
82	    }
83	}
84	
85	/****************************************************************************
86	 * Name: data_timer_cb
87	 *
88	 * Periodically refresh simulated data + real SW3538 readings.
89	 ****************************************************************************/
90	
91	static void data_timer_cb(lv_timer_t *timer)
92	{
93	  static int slow = 0;
94	  struct iron_status_s ist;
95	
96	  cs_ui_data_tick();
97	
98	  /* Sync UI intent (target temp / heater on / PID) into the iron module */
99	  float kp;
100	  float ki;
101	  float kd;
102	
103	  iron_set_target(cs_ui_get_iron_target());
104	  iron_set_heater(cs_ui_get_iron_on());
105	  iron_set_standby_temp(cs_ui_get_standby_temp());
106	  cs_ui_get_iron_pid(&kp, &ki, &kd);
107	  iron_set_pid(kp * 0.2f, ki * 0.4f, kd * 0.2f);
108	
109	  /* Soldering iron: PID tick every 100ms */
110	  iron_tick();
111	  iron_get_status(&ist);
112	  cs_ui_set_iron_real(ist.temp_c, ist.power_pct, ist.heating, ist.sensor_ok);
113	  cs_ui_set_iron_sleep(ist.sleep_active,
114	                       (ist.sleep_active ? ist.target_eff_c : ist.target_c));
115	
116	  /* SW3538 read every 5 ticks (~500ms): 3 ADC conversions take time */
117	  if (++slow >= 5)
118	    {
119	      slow = 0;
120	      sw3538_poll();
121	    }
122	
123	  (void)timer;
124	}
125	
126	/****************************************************************************
127	 * Name: lv_nuttx_loop
128	 *
129	 * Standard LVGL poll loop.
130	 ****************************************************************************/
131	
132	static void lv_nuttx_loop(void)
133	{
134	  while (1)
135	    {
136	      uint32_t idle;
137	
138	      idle = lv_timer_handler();
139	      idle = idle ? idle : 1;
140	      usleep(idle * 1000);
141	    }
142	}
143	
144	/****************************************************************************
145	 * Public Functions
146	 ****************************************************************************/
147	
148	int main(int argc, FAR char *argv[])
149	{
150	  lv_nuttx_dsc_t info;
151	  lv_nuttx_result_t result;
152	
153	  syslog(LOG_INFO, "Charging Station starting\n");
154	
155	  /* Init soldering iron GPIO + MAX6675 probe (non-fatal) */
156	  iron_init();
157	
158	  /* Init the shared I2C4/TCA9548A bus and probe four SW3538 modules. */
159	  if (sw3538_init(SW3538_I2C_BUS) < 0)
160	    {
161	      syslog(LOG_WARNING, "Charging Station: TCA9548A not detected\n");
162	    }
163	  else
164	    {
165	      int channel;
166	
167	      for (channel = 0; channel < 4; channel++)
168	        {
169	          struct sw3538_status_s st;
170	
171	          if (sw3538_read_status_channel(channel, &st) == OK)
172	            {
173	              g_sw3538_ok[channel] = true;
174	              syslog(LOG_INFO, "Charging Station: SW3538 CH%d ready\n",
175	                     channel + 1);
176	            }
177	          else
178	            {
179	              syslog(LOG_WARNING, "Charging Station: SW3538 CH%d absent\n",
180	                     channel + 1);
181	            }
182	        }
183	    }
184	
185	  lv_init();
186	
187	  lv_nuttx_dsc_init(&info);
188	
189	#ifdef CONFIG_LV_USE_NUTTX_LCD
190	  info.fb_path = "/dev/lcd0";
191	#endif
192	
193	  lv_nuttx_init(&info, &result);
194	
195	  if (result.disp == NULL)
196	    {
197	      syslog(LOG_ERR, "Charging Station: display init failed\n");
198	      lv_deinit();
199	      return -1;
200	    }
201	
202	  /* Build the charging station UI */
203	  if (cs_ui_init(lv_screen_active()) < 0)
204	    {
205	      syslog(LOG_ERR, "Charging Station: UI init failed\n");
206	      lv_nuttx_deinit(&result);
207	      lv_deinit();
208	      return -1;
209	    }
210	
211	  /* Start data simulation timer (100ms) */
212	  lv_timer_create(data_timer_cb, 100, NULL);
213	
214	  syslog(LOG_INFO, "Charging Station: display res=%ldx%ld\n",
215	         (long)lv_display_get_horizontal_resolution(result.disp),
216	         (long)lv_display_get_vertical_resolution(result.disp));
217	
218	  if (result.indev)
219	    {
220	      /* Speed up touch reading: 20ms poll period (faster response) */
221	      lv_indev_set_mode(result.indev, LV_INDEV_MODE_TIMER);
222	      lv_timer_t *t = lv_indev_get_read_timer(result.indev);
223	      if (t)
224	        {
225	          lv_timer_set_period(t, 20);
226	        }
227	      syslog(LOG_INFO, "Charging Station: touchscreen registered (20ms poll)\n");
228	    }
229	  else
230	    {
231	      syslog(LOG_WARNING, "Charging Station: no touchscreen (indev NULL)\n");
232	    }
233	
234	  /* Enter the LVGL event loop */
235	  syslog(LOG_INFO, "Charging Station: entering poll loop\n");
236	  lv_nuttx_loop();
237	
238	  lv_nuttx_deinit(&result);
239	  lv_deinit();
240	  return 0;
