/****************************************************************************
 * Contest 2026 team 008 - software (bit-bang) I2C bus
 *
 * Wraps the generic NuttX i2c_bitbang engine (CONFIG_I2C_BITBANG) with
 * STM32H7 GPIO operations so that plain GPIO pins can host an I2C bus.
 *
 * Wiring (Arduino headers):
 *   SCL -> D5 (PA8)
 *   SDA -> D4 (PE4)
 *
 * Both pins are driven open drain: writing 0 drives the line low, writing
 * 1 releases it (input with pull-up) so the external pull-up wins.
 * A 4.7k pull-up from each line to 3.3V is required on the carrier board.
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdint.h>
#include <stdbool.h>
#include <debug.h>

#include <nuttx/arch.h>
#include <nuttx/kmalloc.h>
#include <nuttx/i2c/i2c_master.h>
#include <nuttx/i2c/i2c_bitbang.h>

#include "cs_i2c_sw.h"

/* Chip headers are not on the app include path; the generic GPIO API is
 * declared here and pinsets are built from the documented bit layout:
 *   MODE bits18-19 (OUTPUT=1<<18), SPEED bits10-11 (50MHz=2<<10),
 *   OPEN-DRAIN bit9, OUTPUT_SET bit8, PUPD bits16-17 (PULLUP=1<<16),
 *   PORT bits4-7 (A=0,E=4), PIN bits0-3
 */

extern int  stm32_configgpio(uint32_t cfgset);
extern void stm32_gpiowrite(uint32_t pinset, bool value);
extern bool stm32_gpioread(uint32_t pinset);

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define GPIO_OUTPUT_VAL     (1u << 18)
#define GPIO_SPEED_50MHZ    (2u << 10)
#define GPIO_OUTPUT_SETBIT  (1u << 8)
#define GPIO_OPENDRAIN_VAL  (1u << 9)
#define GPIO_PULLUP         (1u << 16)

#define CS_I2C_SCL_PIN      (GPIO_OUTPUT_VAL | GPIO_SPEED_50MHZ | \
                             GPIO_OPENDRAIN_VAL | GPIO_OUTPUT_SETBIT | \
                             GPIO_PULLUP | (0u << 4) | 8u)   /* D5 = PA8 */
#define CS_I2C_SDA_PIN      (GPIO_OUTPUT_VAL | GPIO_SPEED_50MHZ | \
                             GPIO_OPENDRAIN_VAL | GPIO_OUTPUT_SETBIT | \
                             GPIO_PULLUP | (4u << 4) | 4u)   /* D4 = PE4 */

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct cs_i2c_priv_s
{
  uint32_t scl;    /* SCL pinset */
  uint32_t sda;    /* SDA pinset */
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct cs_i2c_priv_s g_cs_i2c_priv =
{
  CS_I2C_SCL_PIN,
  CS_I2C_SDA_PIN
};

static struct i2c_bitbang_lower_dev_s g_cs_i2c_lower;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void cs_i2c_initialize(FAR struct i2c_bitbang_lower_dev_s *lower)
{
  FAR struct cs_i2c_priv_s *priv = lower->priv;

  stm32_configgpio(priv->scl);
  stm32_configgpio(priv->sda);
}

static void cs_i2c_set_scl(FAR struct i2c_bitbang_lower_dev_s *lower,
                           bool high)
{
  FAR struct cs_i2c_priv_s *priv = lower->priv;

  stm32_gpiowrite(priv->scl, high);
}

static void cs_i2c_set_sda(FAR struct i2c_bitbang_lower_dev_s *lower,
                           bool high)
{
  FAR struct cs_i2c_priv_s *priv = lower->priv;

  stm32_gpiowrite(priv->sda, high);
}

static bool cs_i2c_get_scl(FAR struct i2c_bitbang_lower_dev_s *lower)
{
  FAR struct cs_i2c_priv_s *priv = lower->priv;

  return stm32_gpioread(priv->scl);
}

static bool cs_i2c_get_sda(FAR struct i2c_bitbang_lower_dev_s *lower)
{
  FAR struct cs_i2c_priv_s *priv = lower->priv;

  return stm32_gpioread(priv->sda);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

FAR struct i2c_master_s *cs_i2c_sw_init(void)
{
  static const struct i2c_bitbang_lower_ops_s ops =
  {
    cs_i2c_initialize,
    cs_i2c_set_scl,
    cs_i2c_set_sda,
    cs_i2c_get_scl,
    cs_i2c_get_sda
  };

  g_cs_i2c_lower.ops  = &ops;
  g_cs_i2c_lower.priv = &g_cs_i2c_priv;

  return i2c_bitbang_initialize(&g_cs_i2c_lower);
}

/****************************************************************************
 * Contest 2026 team 008 - SW3538 fast-charge chip driver (NuttX)
 *
 * Four SW3538 devices share I2C address 0x3c behind a TCA9548A at 0x70.
 * Each transaction selects exactly one TCA downstream channel first.
 *
 * The mux (and later the INA226 power monitors) hang off the dedicated
 * software I2C bus so they do not share I2C4 with the FT5x06 touchscreen
 * and the audio codec.
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <debug.h>

#include <nuttx/i2c/i2c_master.h>
#include <nuttx/arch.h>
#include <arch/board/board.h>

#include "cs_i2c_sw.h"
#include "sw3538.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define SW3538_ADDR              0x3c
#define TCA9548A_ADDR            0x70
#define SW3538_FREQ              100000
#define SW3538_CHANNEL_COUNT     4

#define SW3538_REG_PROTO         0x09
#define SW3538_REG_ONLINE        0x0d
#define SW3538_REG_ADC_SEL       0x40
#define SW3538_REG_ADC_LO        0x41
#define SW3538_REG_ADC_HI        0x42
#define SW3538_REG_NTC_CURRENT   0x44

#define ADC_CH_IC                1
#define ADC_CH_IA                2
#define ADC_CH_VOUT              5
#define ADC_CH_NTC               7

#define NTC_UV_PER_BIT           1200u
#define NTC_CURRENT_LOW_UA       20u
#define NTC_CURRENT_HIGH_UA      40u

/****************************************************************************
 * Private Data
 ****************************************************************************/

static FAR struct i2c_master_s *g_i2c;

/* 104AT 100K NTC nominal resistance table.  The values must be calibrated
 * against the actual module at room temperature before they are relied upon
 * for thermal decisions.  This driver reports invalid data rather than a
 * fabricated temperature for values outside the supported table. */

struct ntc_point_s
{
  int16_t temp_c;
  uint32_t resistance_ohm;
};

static const struct ntc_point_s g_ntc_104at[] =
{
  {  0, 355000 }, { 10, 202000 }, { 20, 125000 }, { 25, 100000 },
  { 30,  80500 }, { 40,  51000 }, { 50,  33500 }, { 60,  22400 },
  { 70,  15300 }, { 80,  10600 }, { 90,   7400 }, {100,   5250 },
  {110,   3800 }, {120,   2800 },
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static int tca9548a_write(uint8_t value)
{
  struct i2c_msg_s msg;

  if (g_i2c == NULL)
    {
      return -ENODEV;
    }

  msg.frequency = SW3538_FREQ;
  msg.addr = TCA9548A_ADDR;
  msg.flags = 0;
  msg.buffer = &value;
  msg.length = 1;
  return I2C_TRANSFER(g_i2c, &msg, 1);
}

static int tca9548a_select(uint8_t channel)
{
  if (channel >= SW3538_CHANNEL_COUNT)
    {
      return -EINVAL;
    }

  return tca9548a_write((uint8_t)(1u << channel));
}

static int sw3538_read_regs(uint8_t reg, uint8_t *buf, int len)
{
  struct i2c_msg_s msg[2];
  uint8_t regaddr = reg;

  if (g_i2c == NULL)
    {
      return -ENODEV;
    }

  msg[0].frequency = SW3538_FREQ;
  msg[0].addr = SW3538_ADDR;
  msg[0].flags = 0;
  msg[0].buffer = &regaddr;
  msg[0].length = 1;

  msg[1].frequency = SW3538_FREQ;
  msg[1].addr = SW3538_ADDR;
  msg[1].flags = I2C_M_READ;
  msg[1].buffer = buf;
  msg[1].length = len;

  return I2C_TRANSFER(g_i2c, msg, 2);
}

static int sw3538_write_reg(uint8_t reg, uint8_t val)
{
  struct i2c_msg_s msg;
  uint8_t tx[2] = { reg, val };

  if (g_i2c == NULL)
    {
      return -ENODEV;
    }

  msg.frequency = SW3538_FREQ;
  msg.addr = SW3538_ADDR;
  msg.flags = 0;
  msg.buffer = tx;
  msg.length = sizeof(tx);
  return I2C_TRANSFER(g_i2c, &msg, 1);
}

static int sw3538_adc_code(uint8_t channel, FAR uint16_t *code)
{
  uint8_t lo;
  uint8_t hi;
  int ret;

  if (code == NULL)
    {
      return -EINVAL;
    }

  ret = sw3538_write_reg(SW3538_REG_ADC_SEL, channel);
  if (ret < 0)
    {
      return ret;
    }

  up_udelay(5000);

  ret = sw3538_read_regs(SW3538_REG_ADC_LO, &lo, 1);
  if (ret < 0)
    {
      return ret;
    }

  ret = sw3538_read_regs(SW3538_REG_ADC_HI, &hi, 1);
  if (ret < 0)
    {
      return ret;
    }

  *code = (uint16_t)(((uint16_t)(hi & 0x0f) << 8) | lo);
  return OK;
}

static bool sw3538_ntc_to_temp(uint16_t code, uint8_t ntc_current,
                               FAR int16_t *temp_c)
{
  uint32_t current_ua;
  uint32_t resistance;
  unsigned int i;

  if (code == 0 || temp_c == NULL)
    {
      return false;
    }

  current_ua = (ntc_current & 0x80) ? NTC_CURRENT_HIGH_UA :
                                      NTC_CURRENT_LOW_UA;
  resistance = ((uint32_t)code * NTC_UV_PER_BIT) / current_ua;

  if (resistance > g_ntc_104at[0].resistance_ohm ||
      resistance < g_ntc_104at[(sizeof(g_ntc_104at) /
                                 sizeof(g_ntc_104at[0])) - 1].resistance_ohm)
    {
      return false;
    }

  for (i = 0; i < (sizeof(g_ntc_104at) / sizeof(g_ntc_104at[0])) - 1; i++)
    {
      const struct ntc_point_s *high = &g_ntc_104at[i];
      const struct ntc_point_s *low = &g_ntc_104at[i + 1];

      if (resistance <= high->resistance_ohm &&
          resistance >= low->resistance_ohm)
        {
          uint32_t span = high->resistance_ohm - low->resistance_ohm;
          uint32_t offset = high->resistance_ohm - resistance;

          *temp_c = (int16_t)(high->temp_c +
                    ((int32_t)offset * (low->temp_c - high->temp_c) / span));
          return true;
        }
    }

  return false;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: sw3538_init
 *
 * Description:
 *   Bring up the dedicated software I2C bus and probe the TCA9548A.
 *   The bus parameter is accepted for source compatibility but unused.
 *
 * Returned Value:
 *   OK on success or a negative error.
 *
 ****************************************************************************/

int sw3538_init(int bus)
{
  int ret;

  (void)bus;

  g_i2c = cs_i2c_sw_init();
  if (g_i2c == NULL)
    {
      ierr("SW3538: failed to create software I2C bus\n");
      return -ENODEV;
    }

  ret = tca9548a_write(0);
  if (ret < 0)
    {
      ierr("SW3538: no TCA9548A ACK at 0x%02x\n", TCA9548A_ADDR);
      return ret;
    }

  iinfo("SW3538: TCA9548A ready at 0x%02x on software I2C "
        "(SCL=D5/PA8, SDA=D4/PE4)\n", TCA9548A_ADDR);
  return OK;
}

/* Expose the bus so the INA226 monitors on the same (muxed) bus can share
 * it instead of creating a second bit-bang instance. */

FAR struct i2c_master_s *sw3538_get_bus(void)
{
  return g_i2c;
}

int sw3538_read_status_channel(uint8_t channel,
                                FAR struct sw3538_status_s *st)
{
  uint16_t code;
  uint8_t proto;
  uint8_t online;
  uint8_t ntc_current;
  int ret;

  if (st == NULL)
    {
      return -EINVAL;
    }

  memset(st, 0, sizeof(*st));

  ret = tca9548a_select(channel);
  if (ret < 0)
    {
      return ret;
    }

  ret = sw3538_read_regs(SW3538_REG_PROTO, &proto, 1);
  if (ret < 0)
    {
      return ret;
    }

  ret = sw3538_read_regs(SW3538_REG_ONLINE, &online, 1);
  if (ret < 0)
    {
      return ret;
    }

  ret = sw3538_adc_code(ADC_CH_VOUT, &code);
  if (ret < 0)
    {
      return ret;
    }
  st->vout_mv = (uint16_t)(code * 6u);

  ret = sw3538_adc_code(ADC_CH_IC, &code);
  if (ret < 0)
    {
      return ret;
    }
  st->ic_ma = (uint16_t)(code * 25u / 10u);

  ret = sw3538_adc_code(ADC_CH_IA, &code);
  if (ret < 0)
    {
      return ret;
    }
  st->ia_ma = (uint16_t)(code * 25u / 10u);

  ret = sw3538_read_regs(SW3538_REG_NTC_CURRENT, &ntc_current, 1);
  if (ret < 0)
    {
      return ret;
    }

  ret = sw3538_adc_code(ADC_CH_NTC, &code);
  if (ret < 0)
    {
      return ret;
    }

  st->temp_valid = sw3538_ntc_to_temp(code, ntc_current, &st->temp_c);
  st->proto = proto & 0x0f;
  st->online = online & 0x03;
  return OK;
}

int sw3538_read_status(FAR struct sw3538_status_s *st)
{
  return sw3538_read_status_channel(0, st);
}

const char *sw3538_proto_name(uint8_t proto)
{
  switch (proto)
    {
      case 0:  return "IDLE";
      case 1:  return "QC2.0";
      case 2:  return "QC3.0";
      case 3:  return "QC3+";
      case 4:  return "FCP";
      case 5:  return "SCP";
      case 6:  return "PD";
      case 7:  return "PD-PPS";
      case 8:  return "PE1.1";
      case 9:  return "PE2.0";
      case 10: return "VOOC1";
      case 11: return "VOOC4";
      case 13: return "SFCP";
      case 14: return "AFC";
      case 15: return "TFCP";
      default: return "?";
    }
}

