/****************************************************************************
 * Contest 2026 team 008 - INA226 power monitor header
 *
 * Two INA226 monitors sit behind the TCA9548A:
 *   CH4 -> total power input current
 *   CH5 -> soldering iron heater current
 *
 * Both use address 0x40 (A1 and A0 tied to GND) and are told apart by the
 * multiplexer channel only.
 ****************************************************************************/

#ifndef __INA226_H
#define __INA226_H

#include <stdbool.h>
#include <stdint.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define CS_INA226_TOTAL         0u   /* TCA9548A CH4 */
#define CS_INA226_IRON          1u   /* TCA9548A CH5 */
#define CS_INA226_COUNT         2u

/****************************************************************************
 * Public Types
 ****************************************************************************/

struct ina226_sample_s
{
  uint32_t bus_mv;      /* Bus voltage in mV        (1.25 mV/LSB) */
  int32_t  shunt_uv;    /* Shunt drop in uV         (2.5 uV/LSB, signed) */
  int32_t  current_ma;  /* Current in mA            (signed) */
  uint32_t power_mw;    /* Power in mW              */
};

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

/* Probe and configure both monitors.  Missing devices are reported once and
 * skipped; the call itself succeeds as long as the bus came up. */

int  cs_ina226_init(void);

/* Read one monitor.  Returns -ENODEV without touching the bus when the
 * device is known to be absent. */

int  cs_ina226_read(uint8_t dev, FAR struct ina226_sample_s *out);

/* True when the given monitor answered its last access. */

bool cs_ina226_present(uint8_t dev);

/* Re-probe the monitors that are currently marked absent.  Call at a slow
 * rate (a few seconds) so a missing board costs almost nothing. */

void cs_ina226_retry(void);

#endif /* __INA226_H */

/****************************************************************************
 * Contest 2026 team 008 - INA226 power monitor driver
 *
 * Two INA226 shunt monitors behind the TCA9548A (see cs_i2c_sw.h):
 *   CH4 -> total power input current
 *   CH5 -> soldering iron heater current
 *
 * This is a register level driver, not a character device: the application
 * polls both monitors from its own timer, and both share address 0x40 so
 * they must be addressed through cs_i2c_transfer()'s channel selection.
 *
 * Register map (datasheet section 7.6):
 *   0x00 Configuration   0x01 Shunt Voltage   0x02 Bus Voltage
 *   0x03 Power           0x04 Current         0x05 Calibration
 *   0xFE Manufacturer ID (0x5449 = 'TI')
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include <errno.h>
#include <debug.h>

#include <nuttx/arch.h>

#include "cs_i2c_sw.h"
#include "ina226.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Shunt resistor values in micro-ohms.  THESE MUST MATCH THE HARDWARE: an
 * error here scales both the current and the power reading by the same
 * factor.  The driver prints the resulting current LSB at start-up so the
 * value can be checked against a bench meter.
 */

#define CS_INA226_TOTAL_SHUNT_UOHM   2000u  /* 2 mOhm, TODO confirm */
#define CS_INA226_IRON_SHUNT_UOHM    2000u  /* 2 mOhm, TODO confirm */

/* Target current resolution in micro-amps.  The INA226 datasheet suggests
 * picking a round value near Max_Expected_Current / 32768 so that the
 * current and power registers come out in convenient units. */

#define CS_INA226_TOTAL_LSB_UA       1000u  /* 1 mA  -> +/-32.767 A */
#define CS_INA226_IRON_LSB_UA         500u  /* 0.5 mA -> +/-16.383 A */

#define CS_INA226_ADDR               0x40   /* A1 = A0 = GND */

#define CS_INA226_REG_CONFIG         0x00
#define CS_INA226_REG_SHUNT          0x01
#define CS_INA226_REG_BUS            0x02
#define CS_INA226_REG_POWER          0x03
#define CS_INA226_REG_CURRENT        0x04
#define CS_INA226_REG_CALIBRATION    0x05
#define CS_INA226_REG_MANUFACTURER   0xfe
#define CS_INA226_REG_DIE            0xff

#define CS_INA226_MANUFACTURER_ID    0x5449   /* 'TI' */

/* Configuration register: AVG=16 samples, 1.1ms bus + 1.1ms shunt
 * conversions, continuous shunt and bus mode (datasheet table 5).
 * One full cycle takes 16 x (1.1 + 1.1) ms = 35.2 ms. */

#define CS_INA226_CFG_AVG_16         (2u << 9)
#define CS_INA226_CFG_VBUSCT_1P1MS   (4u << 6)
#define CS_INA226_CFG_VSHCT_1P1MS    (4u << 3)
#define CS_INA226_CFG_MODE_CONT      (7u << 0)
#define CS_INA226_CFG_DEFAULT        (CS_INA226_CFG_AVG_16 | \
                                      CS_INA226_CFG_VBUSCT_1P1MS | \
                                      CS_INA226_CFG_VSHCT_1P1MS | \
                                      CS_INA226_CFG_MODE_CONT)

#define CS_INA226_CONFIG_RESET       (1u << 15)

/* Give up on a device after this many consecutive failed reads. */

#define CS_INA226_MAX_ERRORS         3

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct cs_ina226_dev_s
{
  uint8_t  channel;      /* TCA9548A downstream channel */
  uint32_t shunt_uohm;   /* Shunt resistor in micro-ohms */
  uint16_t cal;          /* Value written to the calibration register */
  uint32_t lsb_na;       /* Effective current LSB in nA */
  uint8_t  errors;       /* Consecutive read failures */
  bool     present;      /* Device answered the last access */
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct cs_ina226_dev_s g_ina226[CS_INA226_COUNT] =
{
  {
    CS_TCA_CH_INA_TOTAL, CS_INA226_TOTAL_SHUNT_UOHM, 0, 0, 0, false
  },
  {
    CS_TCA_CH_INA_IRON,  CS_INA226_IRON_SHUNT_UOHM,  0, 0, 0, false
  }
};

static bool g_ina226_bus_warned;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: cs_ina226_read_reg
 *
 * Read a 16-bit register using a repeated start, as shown in the datasheet
 * timing diagram (figure 23).
 ****************************************************************************/

static int cs_ina226_read_reg(FAR struct cs_ina226_dev_s *dev, uint8_t reg,
                              FAR uint16_t *value)
{
  struct i2c_msg_s msg[2];
  uint8_t regaddr = reg;
  uint8_t buf[2];
  int ret;

  msg[0].frequency = CS_I2C_FREQ;
  msg[0].addr      = CS_INA226_ADDR;
  msg[0].flags     = I2C_M_NOSTOP;   /* Keep the bus for the read */
  msg[0].buffer    = &regaddr;
  msg[0].length    = 1;

  msg[1].frequency = CS_I2C_FREQ;
  msg[1].addr      = CS_INA226_ADDR;
  msg[1].flags     = I2C_M_READ;
  msg[1].buffer    = buf;
  msg[1].length    = 2;

  ret = cs_i2c_transfer(dev->channel, msg, 2);
  if (ret < 0)
    {
      return ret;
    }

  *value = (uint16_t)(((uint16_t)buf[0] << 8) | (uint16_t)buf[1]);
  return OK;
}

/****************************************************************************
 * Name: cs_ina226_write_reg
 ****************************************************************************/

static int cs_ina226_write_reg(FAR struct cs_ina226_dev_s *dev, uint8_t reg,
                               uint16_t value)
{
  struct i2c_msg_s msg;
  uint8_t tx[3];

  tx[0] = reg;
  tx[1] = (uint8_t)(value >> 8);
  tx[2] = (uint8_t)(value & 0xff);

  msg.frequency = CS_I2C_FREQ;
  msg.addr      = CS_INA226_ADDR;
  msg.flags     = 0;
  msg.buffer    = tx;
  msg.length    = sizeof(tx);

  return cs_i2c_transfer(dev->channel, &msg, 1);
}

/****************************************************************************
 * Name: cs_ina226_calibrate
 *
 * Program the calibration register from the shunt value.
 *
 *   CAL = 0.00512 / (Current_LSB[A] * R_shunt[ohm])
 *       = 5.12e9   / (Current_LSB[uA] * R_shunt[uohm])
 *
 * The result is truncated to an integer register, so the current LSB is
 * recomputed from the value actually written.  Skipping that step leaves a
 * fixed gain error of up to one part in 65535 in every current reading.
 *
 * Returned Value:
 *   OK, or -ERANGE when no usable calibration value exists for this shunt.
 ****************************************************************************/

static int cs_ina226_calibrate(FAR struct cs_ina226_dev_s *dev,
                               uint32_t lsb_ua)
{
  uint64_t cal;

  cal = 5120000000ull / ((uint64_t)lsb_ua * (uint64_t)dev->shunt_uohm);
  if (cal < 1 || cal > 65535)
    {
      ierr("INA226 ch%u: shunt %lu uOhm cannot be calibrated with a %lu uA "
           "LSB (cal=%llu)\n", dev->channel,
           (unsigned long)dev->shunt_uohm, (unsigned long)lsb_ua,
           (unsigned long long)cal);
      return -ERANGE;
    }

  dev->cal    = (uint16_t)cal;
  dev->lsb_na = (uint32_t)(5120000000000ull / (cal * dev->shunt_uohm));
  return OK;
}

/****************************************************************************
 * Name: cs_ina226_probe
 *
 * Identify the device and bring it into continuous conversion mode.
 ****************************************************************************/

static int cs_ina226_probe(FAR struct cs_ina226_dev_s *dev)
{
  uint32_t lsb_ua;
  uint16_t id;
  int ret;

  ret = cs_ina226_read_reg(dev, CS_INA226_REG_MANUFACTURER, &id);
  if (ret < 0)
    {
      return ret;
    }

  if (id != CS_INA226_MANUFACTURER_ID)
    {
      iwarn("INA226 ch%u: bad manufacturer ID 0x%04x\n", dev->channel, id);
      return -ENODEV;
    }

  lsb_ua = (dev == &g_ina226[CS_INA226_IRON]) ? CS_INA226_IRON_LSB_UA :
                                                CS_INA226_TOTAL_LSB_UA;

  if (cs_ina226_calibrate(dev, lsb_ua) < 0)
    {
      return -ERANGE;
    }

  /* Reset, then configure for continuous conversion. */

  ret = cs_ina226_write_reg(dev, CS_INA226_REG_CONFIG, CS_INA226_CONFIG_RESET);
  if (ret < 0)
    {
      return ret;
    }

  up_udelay(1000);

  ret = cs_ina226_write_reg(dev, CS_INA226_REG_CONFIG, CS_INA226_CFG_DEFAULT);
  if (ret < 0)
    {
      return ret;
    }

  ret = cs_ina226_write_reg(dev, CS_INA226_REG_CALIBRATION, dev->cal);
  if (ret < 0)
    {
      return ret;
    }

  iinfo("INA226 ch%u: %lu uOhm shunt, LSB=%lu uA, cal=%u (%lu nA/count)\n",
        dev->channel, (unsigned long)dev->shunt_uohm,
        (unsigned long)lsb_ua, dev->cal, (unsigned long)dev->lsb_na);
  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int cs_ina226_init(void)
{
  unsigned int i;
  int ret;

  if (!cs_i2c_bus_ready())
    {
      ret = cs_i2c_bus_init();
      if (ret < 0)
        {
          return ret;
        }
    }

  for (i = 0; i < CS_INA226_COUNT; i++)
    {
      if (cs_ina226_probe(&g_ina226[i]) < 0)
        {
          /* One report per device, then stay quiet until cs_ina226_retry()
           * finds it again. */

          iwarn("INA226: monitor %u not detected on TCA ch%u\n", i,
                g_ina226[i].channel);
          g_ina226[i].present = false;
        }
      else
        {
          g_ina226[i].present = true;
          g_ina226[i].errors  = 0;
        }
    }

  return OK;
}

bool cs_ina226_present(uint8_t dev)
{
  if (dev >= CS_INA226_COUNT)
    {
      return false;
    }

  return g_ina226[dev].present;
}

int cs_ina226_read(uint8_t dev, FAR struct ina226_sample_s *out)
{
  FAR struct cs_ina226_dev_s *d;
  uint16_t raw;
  int ret;

  if (dev >= CS_INA226_COUNT || out == NULL)
    {
      return -EINVAL;
    }

  d = &g_ina226[dev];
  if (!d->present)
    {
      /* Do not burn four ACK timeouts per poll on a board that is not
       * plugged in. */

      return -ENODEV;
    }

  if (!cs_i2c_bus_ready())
    {
      if (!g_ina226_bus_warned)
        {
          g_ina226_bus_warned = true;
          iwarn("INA226: software I2C bus unavailable\n");
        }

      return -ENODEV;
    }

  ret = cs_ina226_read_reg(d, CS_INA226_REG_BUS, &raw);
  if (ret < 0)
    {
      goto lost;
    }

  out->bus_mv = (uint32_t)(raw & 0x7fff) * 5u / 4u;

  ret = cs_ina226_read_reg(d, CS_INA226_REG_SHUNT, &raw);
  if (ret < 0)
    {
      goto lost;
    }

  out->shunt_uv = (int32_t)(int16_t)raw * 5 / 2;

  ret = cs_ina226_read_reg(d, CS_INA226_REG_CURRENT, &raw);
  if (ret < 0)
    {
      goto lost;
    }

  out->current_ma = (int32_t)(((int64_t)(int16_t)raw * d->lsb_na) / 1000000);

  ret = cs_ina226_read_reg(d, CS_INA226_REG_POWER, &raw);
  if (ret < 0)
    {
      goto lost;
    }

  /* Power LSB is 25 x Current LSB. */

  out->power_mw = (uint32_t)(((uint64_t)raw * 25ull * d->lsb_na) /
                             1000000ull);

  d->errors = 0;
  return OK;

lost:
  if (++d->errors >= CS_INA226_MAX_ERRORS)
    {
      d->errors  = 0;
      d->present = false;
      iwarn("INA226: monitor %u lost on TCA ch%u\n", dev, d->channel);
    }

  return ret;
}

void cs_ina226_retry(void)
{
  static const uint32_t lsb_ua[CS_INA226_COUNT] =
  {
    CS_INA226_TOTAL_LSB_UA, CS_INA226_IRON_LSB_UA
  };

  unsigned int i;

  if (!cs_i2c_bus_ready())
    {
      return;
    }

  for (i = 0; i < CS_INA226_COUNT; i++)
    {
      FAR struct cs_ina226_dev_s *d = &g_ina226[i];

      if (d->present)
        {
          continue;
        }

      if (cs_ina226_calibrate(d, lsb_ua[i]) < 0)
        {
          continue;
        }

      if (cs_ina226_probe(d) == OK)
        {
          d->present = true;
          d->errors  = 0;
          iinfo("INA226: monitor %u reappeared on TCA ch%u\n", i, d->channel);
        }
    }
}

