 * Four SW3538 devices share I2C address 0x3c behind a TCA9548A at 0x70.
 * Each transaction selects exactly one TCA downstream channel first.
 *
 * The multiplexer hangs off the software I2C bus (see cs_i2c_sw.c), so it
 * does not share I2C4 with the FT5x06 touchscreen and the audio codec.
 * All bus access goes through cs_i2c_transfer(), which re-selects the
 * channel on every call and holds a lock across select + transfer.
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <debug.h>

#include <nuttx/i2c/i2c_master.h>
#include <nuttx/arch.h>
#include <arch/board/board.h>

#include "cs_i2c_sw.h"
#include "sw3538.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define SW3538_ADDR              0x3c
#define SW3538_CHANNEL_COUNT     4

