static int tca9548a_write(uint8_t value)
{
  struct i2c_msg_s msg;

  if (g_i2c == NULL)
    {
      return -ENODEV;
    }

  msg.frequency = SW3538_FREQ;
  msg.addr = TCA9548A_ADDR;
  msg.flags = 0;
  msg.buffer = &value;
  msg.length = 1;
  return I2C_TRANSFER(g_i2c, &msg, 1);
}

static int tca9548a_select(uint8_t channel)
{
  if (channel >= SW3538_CHANNEL_COUNT)
    {
      return -EINVAL;
    }

  return tca9548a_write((uint8_t)(1u << channel));
}

static int sw3538_read_regs(uint8_t reg, uint8_t *buf, int len)
{
  struct i2c_msg_s msg[2];
  uint8_t regaddr = reg;

  if (g_i2c == NULL)
    {
      return -ENODEV;
    }

  msg[0].frequency = SW3538_FREQ;
  msg[0].addr = SW3538_ADDR;
  msg[0].flags = 0;
  msg[0].buffer = &regaddr;
  msg[0].length = 1;

  msg[1].frequency = SW3538_FREQ;
  msg[1].addr = SW3538_ADDR;
  msg[1].flags = I2C_M_READ;
  msg[1].buffer = buf;
  msg[1].length = len;

  return I2C_TRANSFER(g_i2c, msg, 2);
}

static int sw3538_write_reg(uint8_t reg, uint8_t val)
{
  struct i2c_msg_s msg;
  uint8_t tx[2] = { reg, val };

  if (g_i2c == NULL)
    {
      return -ENODEV;
    }

  msg.frequency = SW3538_FREQ;
  msg.addr = SW3538_ADDR;
  msg.flags = 0;
  msg.buffer = tx;
  msg.length = sizeof(tx);
  return I2C_TRANSFER(g_i2c, &msg, 1);
}

static int sw3538_adc_code(uint8_t channel, FAR uint16_t *code)
{
  uint8_t lo;
  uint8_t hi;
  int ret;

  if (code == NULL)
    {
      return -EINVAL;
    }

  ret = sw3538_write_reg(SW3538_REG_ADC_SEL, channel);
  if (ret < 0)
    {
      return ret;
    }

  up_udelay(5000);

  ret = sw3538_read_regs(SW3538_REG_ADC_LO, &lo, 1);
  if (ret < 0)
    {
      return ret;
    }

  ret = sw3538_read_regs(SW3538_REG_ADC_HI, &hi, 1);
  if (ret < 0)
    {
      return ret;
    }

  *code = (uint16_t)(((uint16_t)(hi & 0x0f) << 8) | lo);
  return OK;
}

