int sw3538_read_status_channel(uint8_t channel,
                                FAR struct sw3538_status_s *st)
{
  uint16_t code;
  uint8_t proto;
  uint8_t online;
  uint8_t ntc_current;
  int ret;

  if (st == NULL)
    {
      return -EINVAL;
    }

  memset(st, 0, sizeof(*st));

  ret = tca9548a_select(channel);
  if (ret < 0)
    {
      return ret;
    }

  ret = sw3538_read_regs(SW3538_REG_PROTO, &proto, 1);
  if (ret < 0)
    {
      return ret;
    }

  ret = sw3538_read_regs(SW3538_REG_ONLINE, &online, 1);
  if (ret < 0)
    {
      return ret;
    }

  ret = sw3538_adc_code(ADC_CH_VOUT, &code);
  if (ret < 0)
    {
      return ret;
    }
  st->vout_mv = (uint16_t)(code * 6u);

  ret = sw3538_adc_code(ADC_CH_IC, &code);
  if (ret < 0)
    {
      return ret;
    }
  st->ic_ma = (uint16_t)(code * 25u / 10u);

  ret = sw3538_adc_code(ADC_CH_IA, &code);
  if (ret < 0)
    {
      return ret;
    }
  st->ia_ma = (uint16_t)(code * 25u / 10u);

  ret = sw3538_read_regs(SW3538_REG_NTC_CURRENT, &ntc_current, 1);
  if (ret < 0)
    {
      return ret;
    }

  ret = sw3538_adc_code(ADC_CH_NTC, &code);
  if (ret < 0)
    {
      return ret;
    }

  st->temp_valid = sw3538_ntc_to_temp(code, ntc_current, &st->temp_c);
  st->proto = proto & 0x0f;
  st->online = online & 0x03;
  return OK;
}

