/****************************************************************************
 * Name: cs_ui_set_input_power
 *
 * Total input rail measured by the INA226 behind TCA9548A channel 4.
 * valid=false means the monitor is absent or its last read failed; the
 * banner then shows dashes instead of a fake 0 W.
 ****************************************************************************/

void cs_ui_set_input_power(float volt, float amp, float watt, bool valid)
{
  if (g_input_lbl == NULL)
    {
      return;
    }

  if (!valid)
    {
      lv_label_set_text(g_input_lbl, "INPUT  --.-V  --.--A  --W");
      lv_obj_set_style_text_color(g_input_lbl, COLOR_DIM, 0);
      return;
    }

  lv_label_set_text_fmt(g_input_lbl, "INPUT  %.1fV %.2fA %.1fW",
                        (double)volt, (double)amp, (double)watt);
  lv_obj_set_style_text_color(g_input_lbl,
                              (amp > 0.05f) ? COLOR_OK : COLOR_DIM, 0);
}

/****************************************************************************
 * Name: cs_ui_set_iron_power
 *
 * Heater power measured by the INA226 on TCA9548A channel 5.  The heater is
 * switched by a 1 Hz software PWM, so successive samples toggle between the
 * on and off state; this is why the value is shown next to the PWM duty
 * percentage rather than used on its own.
 ****************************************************************************/

void cs_ui_set_iron_power(float volt, float amp, float watt, bool valid)
{
  if (g_iron_watt_lbl == NULL)
    {
      return;
    }

  if (!valid)
    {
      lv_label_set_text(g_iron_watt_lbl, "--W");
      lv_obj_set_style_text_color(g_iron_watt_lbl, COLOR_IRON_DIM, 0);
      return;
    }

  lv_label_set_text_fmt(g_iron_watt_lbl, "%.0fW", (double)watt);
  lv_obj_set_style_text_color(g_iron_watt_lbl, COLOR_IRON_ACCENT, 0);
}

