static bool max6675_temp(uint16_t raw, FAR float *temp_c)
{
  uint16_t code;

  if (temp_c == NULL || (raw & 0x8000) != 0 || (raw & 0x0002) != 0 ||
      (raw & 0x0004) != 0)
    {
      return false;
    }

  /* An all-zero frame decodes to a perfectly plausible 0.00 C, which is
   * exactly what an unpowered or disconnected MAX6675 returns while its
   * SO pin is held low.  Treating that as a real reading means the PID sees
   * a 350 C error and drives the heater at full power with no thermocouple
   * attached, so reject it instead.  A real thermocouple reads above -1 C
   * even in ice water, so nothing legitimate is lost. */

  if (raw == 0)
    {
      return false;
    }

  code = (raw >> 3) & 0x0fff;
  *temp_c = (float)code * 0.25f;
  return *temp_c >= 0.0f && *temp_c <= 1023.75f;
}

