  msg[0].flags = 0;
  msg[0].buffer = &regaddr;
  msg[0].length = 1;

  msg[1].frequency = CS_I2C_FREQ;
  msg[1].addr = SW3538_ADDR;
  msg[1].flags = I2C_M_READ;
  msg[1].buffer = buf;
