static int sw3538_write_reg(uint8_t channel, uint8_t reg, uint8_t val)
{
  struct i2c_msg_s msg;
  uint8_t tx[2] = { reg, val };

  msg.frequency = CS_I2C_FREQ;
  msg.addr = SW3538_ADDR;
  msg.flags = 0;
  msg.buffer = tx;
