  if (ret < 0)
    {
      return ret;
    }

  ret = sw3538_adc_code(ADC_CH_NTC, &code);
  if (ret < 0)
    {
      return ret;
    }

  st->temp_valid = sw3538_ntc_to_temp(code, ntc_current, &st->temp_c);
  st->proto = proto & 0x0f;
