int sw3538_selfcheck(void)
{
  uint8_t proto;
  uint8_t online;
  uint8_t ch;
  int ret = OK;

  syslog(LOG_INFO, "SW3538 selfcheck: reading identifiable registers "
         "from each channel\n");

  for (ch = 0; ch < SW3538_CHANNEL_COUNT; ch++)
    {
      struct sw3538_status_s st;

      /* Register 0x09 doubles as a link probe: a device that answers here
       * is present and talking. */

      if (cs_i2c_transfer(ch, NULL, 0) == -EINVAL)
        {
          /* channel selection happens inside the read below */
        }

      if (sw3538_read_regs(ch, SW3538_REG_PROTO, &proto, 1) < 0 ||
          sw3538_read_regs(ch, SW3538_REG_ONLINE, &online, 1) < 0)
        {
          syslog(LOG_WARNING, "SW3538 CH%u: no answer\n", ch + 1);
          ret = -ENODEV;
          continue;
        }

      syslog(LOG_INFO,
             "SW3538 CH%u: proto=0x%02x (state b7=%u b6=%u pd=%u code=%u) "
             "online=0x%02x (C=%u A=%u)\n",
             ch + 1, proto, (proto >> 7) & 1u, (proto >> 6) & 1u,
             (proto >> 4) & 3u, proto & 0x0fu,
             online, (online >> 1) & 1u, online & 1u);

      /* Cross-check the port the hardware reports against the current
       * measured on each path.  With a load on the Type-C port only, the
       * path that shows current is the Type-C path -- that is the one
       * measurement that settles the channel mapping question above. */

      if (sw3538_read_status_channel(ch, &st) == OK)
        {
          syslog(LOG_INFO, "SW3538 CH%u: Vout=%umV path1(C?)=%umA "
                 "path2(A?)=%umA\n", ch + 1, st.vout_mv, st.ic_ma, st.ia_ma);
        }
    }

  return ret;
}

