 * Name: iron_sleep_tick
 *
 * Debounce the JBC245 SLEEP pin and drive the sleep stage:
 *   ACTIVE -> HOLD (in stand) -> STANDBY_TEMP after IRON_SLEEP_ENTER_TICKS.
 *   Leave stand at any time: back to ACTIVE and restore the user target.
 ****************************************************************************/

static void iron_sleep_tick(void)
{
  bool raw;
  bool sleep_now;

  raw = !stm32_gpioread(IRON_GPIO_SLEEP);   /* active low: in stand */

  /* Bounce filter: require N consecutive identical samples. */
  if (raw != g_sleep_pin_deb)
    {
      g_sleep_deb_cnt++;
      if (g_sleep_deb_cnt >= IRON_SLEEP_DEBOUNCE_TICKS)
        {
          g_sleep_pin_deb = raw;
          g_sleep_deb_cnt = 0;
        }
    }
  else
    {
      g_sleep_deb_cnt = 0;
    }

  sleep_now = g_sleep_pin_deb;

  if (!sleep_now && g_sleep_stage != IRON_SLEEP_ACTIVE)
    {
      /* Picked up: restore user target and PID history. */
      g_sleep_stage = IRON_SLEEP_ACTIVE;
      g_sleep_ticks = 0;
      g_integral = 0.0f;
      g_last_temp_c = g_temp_c;
      g_target_eff_c = g_target_c;
    }
  else if (sleep_now && g_sleep_stage == IRON_SLEEP_ACTIVE)
    {
      g_sleep_stage = IRON_SLEEP_HOLD;
      g_sleep_ticks = 0;
    }
  else if (g_sleep_stage == IRON_SLEEP_HOLD)
    {
      g_sleep_ticks++;
      if (g_sleep_ticks >= IRON_SLEEP_ENTER_TICKS)
        {
          g_sleep_stage = IRON_SLEEP_STANDBY_TEMP;
          g_integral = 0.0f;
          g_target_eff_c = g_standby_c;
        }
    }
}

